// Dr. MGR BPT Year I Psychology and Sociology topics, linked to physiotherapy practice. Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"ps-psychology-intro", title:"Psychology: definition, schools, methods and branches", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["definition of psychology","schools of psychology","methods of psychology","branches of psychology","structuralism behaviourism","introspection method"],
  simple:"Psychology is the scientific study of behaviour and mental processes such as thinking, feeling and remembering. Over time different schools explained the mind in different ways, and psychologists use methods such as observation and experiment to study it. A physiotherapist uses psychology every day to understand, motivate and teach patients.",
  flow:["Psychology studies behaviour and mental processes scientifically","Wundt starts first laboratory at Leipzig in 1879","Schools: structuralism, functionalism, behaviourism, Gestalt, psychoanalysis, humanistic","Methods: introspection, observation, experiment, case study, survey","Branches apply psychology to health, education, work and sport","Physio uses it to motivate, teach and support patients"],
  exam:[
    {h:"Definition", p:["Psychology is the scientific study of behaviour and mental processes of humans and animals.","The word comes from Greek psyche (soul or mind) and logos (study); early definitions as 'study of soul' and 'study of consciousness' gave way to 'study of behaviour' (Watson) and now behaviour plus mental processes.","Behaviour is any observable action; mental processes are inner events such as perception, memory, thinking and emotion."]},
    {h:"Schools of psychology", p:["Structuralism (Wundt, Titchener): broke conscious experience into elements using trained introspection.","Functionalism (William James, Dewey): asked what the mind does to help adaptation to the environment.","Behaviourism (Watson, Skinner): only observable behaviour is studied; learning by conditioning. Gestalt (Wertheimer, Kohler, Koffka): the whole is more than the sum of parts, studied perception and insight.","Psychoanalysis (Freud): unconscious motives, childhood experience and defence mechanisms. Humanistic (Maslow, Rogers): free will, growth and self-actualisation. Cognitive: mind as an information processor (memory, attention, problem solving)."]},
    {h:"Methods of psychology", p:["Introspection: looking inward and reporting one's own experience; subjective and cannot be used with children or ill patients.","Observation: naturalistic or controlled watching and recording of behaviour; objective but observer bias is possible.","Experimental method: an independent variable is changed and its effect on a dependent variable is measured with controls; most scientific, shows cause and effect.","Case study (clinical method), survey and questionnaire, interview, correlational and psychological testing methods."]},
    {h:"Branches of psychology", p:["Pure: general, developmental (child, adolescent, ageing), abnormal, social, physiological psychology and neuropsychology.","Applied: clinical, counselling, educational, industrial and organisational, health psychology, sports psychology and rehabilitation psychology.","Health and rehabilitation psychology are the branches closest to physiotherapy."]},
    {h:"Relevance to physiotherapy", p:["Understanding patient behaviour, fear and pain beliefs, which strongly affect recovery (biopsychosocial model, Engel 1977).","Applying learning and motivation principles when teaching exercises and motor skills.","Communicating, counselling and building rapport; recognising anxiety, depression and need for referral.","Team work and leadership in the rehabilitation team."]},
    {h:"Conclusion", p:["Psychology moved from philosophy to a science; its methods and branches give the physiotherapist tools to treat the person, not just the joint."]}
  ],
  tip:"Draw a time-line: 1879 Wundt lab, then arrows to each school with its founder and one key word (elements, function, behaviour, whole, unconscious, growth, information processing).",
  evidence:[["Psychologically informed physiotherapy for chronic pain","Better function and less disability than usual care in several trials","Moderate"],["Teaching biopsychosocial pain concepts to clinicians","Changes beliefs and guideline-consistent advice","Low-moderate"]],
  evidenceSource:"Engel, Science 1977 (biopsychosocial model); Morgan and King, Introduction to Psychology",
  outcomes:[["Tampa Scale of Kinesiophobia","Fear of movement"],["HADS","Anxiety and depression in hospital patients"]],
  recent:["Psychologically informed practice (for example cognitive functional therapy and STarT Back stratified care) is now part of physiotherapy care for back pain."],
  mnemonic:{word:"SF-BGPH", items:[["S","Structuralism - Wundt"],["F","Functionalism - James"],["B","Behaviourism - Watson"],["G","Gestalt - Wertheimer"],["P","Psychoanalysis - Freud"],["H","Humanistic - Maslow, Rogers"]], extra:"Add C for the cognitive school."},
  example:"A 35-year-old software engineer in Bengaluru with back pain avoids bending because he believes his disc will 'slip out'. The physiotherapist uses psychology to explore this belief and teach graded bending.",
  flags:["Suicidal talk or hopelessness: refer urgently to psychiatrist or psychologist","Severe depression or anxiety blocking rehab","Never label a patient's pain as 'psychological only'"],
  viva:[["Who started the first psychology laboratory?","Wilhelm Wundt at Leipzig in 1879."],["Which method shows cause and effect?","The experimental method."],["Who founded behaviourism?","John B Watson (1913)."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: The science of psychology."},{c:"Mangal SK. General Psychology. Sterling Publishers. Chapter: Nature, schools and methods of psychology."},{c:"Engel GL. The need for a new medical model: a challenge for biomedicine. Science. 1977;196:129-136.", q:"Engel need for a new medical model challenge for biomedicine"}],
  keywords:"psychology definition schools structuralism functionalism behaviourism gestalt psychoanalysis humanistic methods introspection experiment branches",
  mcq:[["The first psychology laboratory was established by:",["Freud","Watson","Wundt","Skinner"],2,"Wundt opened it at Leipzig in 1879."],["The 'whole is more than the sum of its parts' is the view of:",["Gestalt school","Structuralism","Behaviourism","Functionalism"],0,"Gestalt psychologists studied perception as organised wholes."]]
},
{
  id:"ps-heredity-environment", title:"Heredity and environment: the nature-nurture controversy", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["heredity and environment","nature vs nurture","twin studies","genotype phenotype","epigenetics","role of heredity"],
  simple:"Heredity is what we receive from our parents through genes, like height range or eye colour. Environment is everything around us after conception: food, family, school and culture. Today we know they always work together: genes give the possibilities and the environment decides how far they develop.",
  flow:["Heredity: genes passed from parents at conception","Environment: prenatal, physical, social and cultural surroundings","Nativists stress heredity; empiricists like Watson stress environment","Twin, adoption and family studies test their roles","Modern view: interaction, including epigenetic switching of genes","Physio shapes environment to bring out motor potential"],
  exam:[
    {h:"Definitions", p:["Heredity: the transmission of physical and mental characteristics from parents to offspring through genes on chromosomes (23 pairs in humans).","Environment: the sum of all external influences acting on an individual from conception onwards: prenatal (womb), physical, social, cultural and economic.","Genotype is the genetic make-up; phenotype is the observable result of genotype acting with environment."]},
    {h:"The controversy", p:["Nature side (Galton, hereditarians): abilities and personality are inborn; Galton studied eminent families.","Nurture side (Locke's tabula rasa, Watson): the child is a blank slate; Watson claimed he could train any healthy infant into any profession.","Both extreme views are rejected now; the question is not 'which' but 'how much and how do they interact'."]},
    {h:"Methods of study", p:["Twin studies: identical (monozygotic) twins share all genes, fraternal (dizygotic) share about half; greater similarity in identical twins suggests heredity.","Identical twins reared apart: similarity despite different homes points to heredity; differences point to environment.","Adoption studies compare the child with biological and adoptive parents; family pedigree studies; animal breeding studies."]},
    {h:"Areas of influence", p:["Strongly hereditary: eye colour, blood group, body build, many genetic disorders (Down syndrome, muscular dystrophy, haemophilia).","Shared influence: intelligence, temperament, height (needs nutrition), athletic ability, risk of diseases such as diabetes, hypertension and schizophrenia.","Strongly environmental: language spoken, religion, food habits, values and attitudes."]},
    {h:"Interaction and modern view", p:["Heredity sets the range (reaction range); environment decides the point reached within it.","Epigenetics: environment such as nutrition and stress can switch genes on or off without changing the DNA code.","Maturation (heredity driven) and learning (environment driven) both needed: a child cannot be trained to walk before the nervous system is ready."]},
    {h:"Applied to physiotherapy", p:["Genetic conditions (DMD, SMA, OI) set limits, but physiotherapy, positioning and an enriched environment improve function and participation.","Children with cerebral palsy benefit from early enriched motor experience because the young brain is plastic.","Lifestyle and environment change the expression of inherited risk for obesity, diabetes and heart disease, which exercise prescription targets."]},
    {h:"Conclusion", p:["Behaviour is the product of heredity multiplied by environment; neither alone explains a person, and rehabilitation works by optimising the environment."]}
  ],
  tip:"Draw two overlapping circles labelled Heredity and Environment with Behaviour in the overlap; beside it draw a twin box: MZ (100 percent genes) and DZ (about 50 percent genes).",
  evidence:[["Early enriched motor intervention in infants at risk of CP","Supports motor development during high plasticity","Low-moderate"],["Lifestyle exercise in people with family risk of type 2 diabetes","Reduces progression to diabetes","High"]],
  evidenceSource:"Berk, Child Development; Diabetes Prevention Program trial (NEJM 2002) on lifestyle change in high-risk adults",
  outcomes:[["Developmental milestones","How heredity and environment show in motor progress"],["Family history","Inherited risk to guide prevention"]],
  recent:["Epigenetics research shows that early stress and nutrition can alter gene expression, strengthening the case for early intervention."],
  mnemonic:{word:"TAP", items:[["T","Twin studies"],["A","Adoption studies"],["P","Pedigree (family) studies"]], extra:"Behaviour = Heredity x Environment, not Heredity + Environment."},
  example:"Twin boys born prematurely in Salem: one with periventricular leukomalacia gets early home-based motor stimulation and family training. Both share genes, but their outcome depends on early care and environment.",
  flags:["Do not tell families a genetic condition means 'nothing can be done'","Avoid blaming parents for a hereditary disorder"],
  viva:[["Who said the child is a blank slate?","John Locke (tabula rasa); Watson took the strong environmental view."],["Why are identical twins used in research?","They share all genes, so differences between them point to environment."],["Define phenotype.","The observable traits resulting from genotype interacting with environment."]],
  refs:[{b:"berk",ch:"Biological and environmental foundations"},{b:"hurlock",ch:"Heredity and environment in development"},{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Biological basis of behaviour and heredity."}],
  keywords:"heredity environment nature nurture twin studies adoption genotype phenotype epigenetics galton watson",
  mcq:[["Monozygotic twins share approximately what proportion of their genes?",["25 percent","50 percent","75 percent","100 percent"],3,"Identical twins come from one zygote."],["The tabula rasa concept is associated with:",["Galton","Locke","Freud","Mendel"],1,"Locke described the mind at birth as a blank slate."]]
},
{
  id:"ps-lifespan-development", title:"Development and growth of behaviour from infancy to old age", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["lifespan development","stages of development","Erikson stages","Piaget cognitive development","adolescence","old age psychology","developmental psychology"],
  simple:"From birth to old age people change in body, thinking, emotions and social life. Each stage has its own tasks: a baby learns trust, a teenager builds identity, an adult works and raises family, and an older person looks back on life. Physiotherapists adapt how they teach and motivate according to the patient's stage.",
  flow:["Growth is size change; development is change in function","Infancy: motor milestones, attachment and trust","Childhood: language, play, school skills and peer groups","Adolescence: puberty, identity and peer pressure","Adulthood: work, family and responsibility","Old age: slowing, loss, reflection and integrity"],
  exam:[
    {h:"Definitions and principles", p:["Growth: quantitative increase in size; development: qualitative, orderly change in function across life.","Principles: continuous, sequential, cephalocaudal and proximodistal, general to specific, individual differences, product of maturation and learning."]},
    {h:"Infancy and early childhood (0-6 years)", p:["Motor: head control by 3-4 months, sitting about 6-8 months, walking about 12-15 months; fine grasp develops from palmar to pincer.","Attachment to mother (Bowlby); stranger anxiety around 8 months; Erikson trust vs mistrust, then autonomy vs shame, initiative vs guilt.","Piaget: sensorimotor (0-2 years, object permanence) and preoperational (2-7 years, symbolic play, egocentric thinking)."]},
    {h:"Late childhood and adolescence", p:["Late childhood (6-12): school skills, rules, peer groups; Erikson industry vs inferiority; Piaget concrete operational (conservation, logic about real objects).","Adolescence (about 12-18): puberty, growth spurt, abstract thinking (Piaget formal operations), identity vs role confusion, peer pressure, risk taking, body image concerns."]},
    {h:"Adulthood", p:["Early adulthood: career, marriage, intimacy vs isolation (Erikson).","Middle age: generativity vs stagnation; caring for children and ageing parents; menopause; onset of lifestyle diseases.","Peak physical performance in 20s, gradual decline later; experience and judgement increase."]},
    {h:"Old age", p:["Physical: reduced muscle mass (sarcopenia), balance, vision, hearing, reaction time; higher risk of falls.","Cognitive: slower processing, some memory decline, but knowledge (crystallised intelligence) is maintained; dementia is not normal ageing.","Psychosocial: retirement, loss of spouse and friends, dependence; Erikson integrity vs despair."]},
    {h:"Application in physiotherapy", p:["Children: use play, toys and parents; short sessions; follow developmental sequence in therapy.","Adolescents: respect privacy, involve in goals, address body image (for example scoliosis bracing).","Adults: link exercise to work and family roles. Older adults: slower instructions, safety, fall prevention and preserving independence and dignity."]},
    {h:"Conclusion", p:["Knowing lifespan stages lets the physiotherapist match goals, teaching style and motivation to the patient's age."]}
  ],
  tip:"Draw a ladder of Erikson's eight stages from bottom (trust vs mistrust) to top (integrity vs despair), with Piaget's four stages written alongside the childhood rungs.",
  evidence:[["Play-based, family-involved therapy for children","Better engagement and carry-over at home","Moderate"],["Strength and balance training in older adults","Reduces falls","High"]],
  evidenceSource:"Hurlock, Developmental Psychology: A Life-span Approach; Cochrane review of exercise for preventing falls in older people (Sherrington et al., 2019)",
  outcomes:[["Developmental milestone charts","Child development"],["Timed Up and Go","Mobility and fall risk in older adults"]],
  recent:["The WHO Decade of Healthy Ageing (2021-2030) focuses on maintaining functional ability in older people."],
  mnemonic:{word:"TAIIIGI", items:[["T","Trust vs mistrust"],["A","Autonomy vs shame"],["I","Initiative vs guilt"],["I","Industry vs inferiority"],["I","Identity vs role confusion"],["I","Intimacy vs isolation"],["G","Generativity vs stagnation"]], extra:"Then Integrity vs despair in old age."},
  example:"A 14-year-old girl in Chennai with idiopathic scoliosis refuses to wear her brace to school because classmates tease her. The physiotherapist addresses her body image concerns and involves her in choosing her exercise plan.",
  flags:["Loss of previously gained milestones in a child (regression)","Rapid memory loss or confusion in older adults: screen for dementia or delirium","Signs of child or elder abuse"],
  viva:[["Name Piaget's stages.","Sensorimotor, preoperational, concrete operational, formal operational."],["Erikson's crisis of adolescence?","Identity vs role confusion."],["Which intelligence is preserved in old age?","Crystallised intelligence."]],
  refs:[{b:"hurlock",ch:"Life-span developmental stages"},{b:"berk",ch:"Cognitive and psychosocial development across the life span"},{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Human development."}],
  keywords:"development growth infancy childhood adolescence adulthood old age erikson piaget lifespan",
  mcq:[["Object permanence is achieved in which Piaget stage?",["Preoperational","Concrete operational","Sensorimotor","Formal operational"],2,"It develops during the sensorimotor stage (0-2 years)."],["Erikson's crisis of old age is:",["Generativity vs stagnation","Integrity vs despair","Intimacy vs isolation","Industry vs inferiority"],1,"Older adults review life with integrity or despair."]]
},
{
  id:"ps-intelligence", title:"Intelligence: definition, theories, IQ, mental age and intelligence tests (WAIS, WISC, Bhatia, Raven)", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["intelligence quotient","IQ mental age","WAIS WISC","Bhatia battery","Raven progressive matrices","theories of intelligence","Binet test"],
  simple:"Intelligence is the ability to learn, understand, reason and adapt to new situations. It is measured by tests that give an IQ score, which compares a person's performance with others of the same age. Physiotherapists need this to pitch instructions and home programmes at the right level, especially for children with intellectual disability.",
  flow:["Intelligence: capacity to learn, reason and adapt","Theories: Spearman g, Thurstone, Gardner, Sternberg","Binet introduced mental age; IQ = MA / CA x 100","Tests: verbal, performance, individual and group","WAIS, WISC, Bhatia battery and Raven matrices","IQ guides teaching level and rehab planning"],
  exam:[
    {h:"Definition", p:["Intelligence is the global capacity to act purposefully, think rationally and deal effectively with the environment (Wechsler).","Includes learning ability, abstract thinking, problem solving and adaptation to new situations."]},
    {h:"Theories", p:["Spearman's two-factor theory: general factor (g) plus specific factors (s). Thurstone: seven primary mental abilities (verbal, number, spatial, memory, reasoning, word fluency, perceptual speed).","Guilford's structure of intellect; Cattell's fluid (reasoning, declines with age) and crystallised (knowledge, maintained) intelligence.","Gardner's multiple intelligences (linguistic, logical-mathematical, spatial, bodily-kinaesthetic, musical, interpersonal, intrapersonal, naturalistic); Sternberg's triarchic theory; emotional intelligence (Goleman)."]},
    {h:"Mental age and IQ", p:["Mental age (MA): the age level at which a person performs on a test (Binet and Simon, 1905).","Ratio IQ = (MA / chronological age) x 100; a 10-year-old performing like a 12-year-old has IQ 120.","Modern tests use deviation IQ: mean 100, standard deviation 15. Classification: 130+ very superior, 90-109 average, 70-79 borderline, below 70 intellectual disability (mild 50-69, moderate 35-49, severe 20-34, profound below 20)."]},
    {h:"Intelligence tests", p:["Types: individual vs group, verbal vs non-verbal (performance), culture-fair tests.","WAIS (Wechsler Adult Intelligence Scale, 16 years and above) and WISC (Wechsler Intelligence Scale for Children, about 6-16 years): verbal and performance subtests giving index scores and full-scale IQ.","Bhatia Battery of Performance Tests (C M Bhatia, India): Koh's block design, Alexander's pass-along, pattern drawing, immediate memory and picture construction; useful for Indian and less literate subjects.","Raven's Progressive Matrices: non-verbal pattern completion (Standard, Coloured for children and impaired, Advanced); culture-reduced test of reasoning (g)."]},
    {h:"Uses and limitations", p:["Uses: diagnosis of intellectual disability or giftedness, school placement, vocational guidance, disability certification.","Limitations: cultural and language bias, test anxiety, does not measure creativity or adaptive behaviour; diagnosis of intellectual disability needs adaptive functioning too."]},
    {h:"Relevance to physiotherapy", p:["Adjust instructions: simple steps, demonstration and repetition for low IQ; visual cues for children with intellectual disability.","Children with CP or Down syndrome may have associated intellectual disability; motor goals must match cognitive level.","Bodily-kinaesthetic intelligence is a reminder that motor skill is a form of intelligence that physio training develops."]},
    {h:"Conclusion", p:["IQ is a useful but limited index; the physiotherapist uses it to tailor teaching, not to label the patient."]}
  ],
  tip:"Draw a bell curve with mean 100 and marks at 70, 85, 115 and 130; label the ranges below 70 and above 130.",
  evidence:[["Physical activity programmes in people with intellectual disability","Improve fitness and some functional outcomes","Low-moderate"],["Simplified, visual instructions","Better understanding and adherence in low literacy patients","Low"]],
  evidenceSource:"Morgan and King, Introduction to Psychology; DSM-5 criteria for intellectual disability",
  outcomes:[["Full-scale IQ","Overall intellectual level"],["Vineland Adaptive Behaviour Scales","Adaptive functioning"]],
  recent:["DSM-5 (2013) grades severity of intellectual disability by adaptive functioning rather than by IQ alone."],
  mnemonic:{word:"MAC", items:[["M","Mental age"],["A","divided by Actual (chronological) age"],["C","x 100 = IQ"]], extra:"Raven = Reasoning without words; Bhatia = Blocks and performance."},
  example:"A 9-year-old boy with spastic diplegia in Trichy has a WISC full-scale IQ of 62. The physiotherapist uses picture cards and one-step commands for his gait training home programme.",
  flags:["Do not assume low intelligence from speech or motor impairment (many children with CP have normal IQ)","Test results are invalid if vision, hearing or language are not accounted for"],
  viva:[["Formula for IQ?","Mental age divided by chronological age multiplied by 100."],["Which test is non-verbal and culture-reduced?","Raven's Progressive Matrices."],["WISC is used for which age?","Children of about 6-16 years."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Intelligence and its measurement."},{c:"Mangal SK. General Psychology. Sterling Publishers. Chapter: Intelligence."},{b:"berk",ch:"Intelligence and individual differences"}],
  keywords:"intelligence iq mental age wais wisc bhatia raven binet spearman thurstone gardner tests",
  mcq:[["A child of chronological age 8 years has a mental age of 10 years. Ratio IQ is:",["80","100","125","150"],2,"10/8 x 100 = 125."],["Koh's block design is part of:",["Raven's matrices","Bhatia battery","MMPI","TAT"],1,"Bhatia's performance battery includes Koh's blocks."]]
},
{
  id:"ps-motivation", title:"Motivation: motive, drive, incentive, reinforcement and primary needs", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["motivation cycle","Maslow hierarchy of needs","need drive incentive","intrinsic extrinsic motivation","primary and secondary motives","patient motivation"],
  simple:"Motivation is the inner force that starts, directs and keeps up our behaviour towards a goal. A need creates a drive, the drive pushes us to act, and an incentive pulls us towards the goal. In rehab, a motivated patient does the exercises and recovers better, so physiotherapists must learn how to build motivation.",
  flow:["Need: a lack in the body or mind","Drive: tension that pushes the person to act","Incentive: goal object that pulls behaviour","Goal reached, need reduced, drive falls","Reinforcement strengthens the behaviour for next time","Physio uses goals and rewards to motivate patients"],
  exam:[
    {h:"Definitions", p:["Motivation: the process that arouses, directs and sustains behaviour towards a goal.","Motive: a general term for an internal state that energises behaviour towards a goal (for example need for achievement).","Need: a state of deficiency (biological or psychological). Drive: the aroused tension created by a need that pushes to action (Hull). Incentive: an external goal object or reward that pulls behaviour (food, praise, money).","Reinforcement: any consequence that increases the probability of a behaviour being repeated (positive: adding something pleasant; negative: removing something unpleasant)."]},
    {h:"Motivation cycle", p:["Need, then drive, then goal-directed behaviour, then incentive or goal, then drive reduction and satisfaction.","Homeostasis: the body tries to maintain internal balance; biological drives restore it."]},
    {h:"Classification of motives", p:["Primary (biological, unlearned) needs: hunger, thirst, oxygen, sleep, temperature regulation, avoidance of pain, elimination, sex and maternal drive.","Secondary (learned, social) motives: achievement (McClelland), affiliation, power, approval, curiosity and exploration.","Intrinsic motivation: doing an activity for its own enjoyment; extrinsic motivation: doing it for an outside reward or to avoid punishment."]},
    {h:"Theories", p:["Instinct theory (McDougall); drive-reduction theory (Hull); arousal theory and Yerkes-Dodson law (moderate arousal gives best performance).","Maslow's hierarchy: physiological, safety, love and belonging, esteem, self-actualisation; lower needs must be met first.","Incentive theory; self-determination theory (Deci and Ryan): autonomy, competence and relatedness build intrinsic motivation; Bandura's self-efficacy."]},
    {h:"Motivating patients in physiotherapy", p:["Set SMART goals with the patient that matter to his life roles (walking to temple, returning to work).","Give feedback and praise on progress (charts, video, measured gains); use positive reinforcement.","Build self-efficacy with small successes; give choice (autonomy); involve family and peer groups.","Meet basic needs first: a patient in pain, hungry or afraid cannot engage in exercise (Maslow)."]},
    {h:"Causes of poor motivation", p:["Pain, fatigue, depression, fear of movement, unclear goals, poor understanding, lack of family support, financial worries and slow visible progress."]},
    {h:"Conclusion", p:["Motivation links needs to action; using goals, reinforcement and self-efficacy turns a passive patient into an active partner in rehab."]}
  ],
  tip:"Draw the motivation cycle as a circle: Need, Drive, Behaviour, Goal/Incentive, Satisfaction, back to Need. Beside it draw Maslow's pyramid with five layers.",
  evidence:[["Goal setting in rehabilitation","Probably improves patient engagement and some outcomes","Low-moderate"],["Motivational interviewing in physical activity","Small increases in activity and adherence","Low-moderate"]],
  evidenceSource:"Levack et al., Cochrane review of goal setting in rehabilitation (2015); Maslow, Psychological Review 1943",
  outcomes:[["Goal Attainment Scaling","Achievement of patient-set goals"],["Pain Self-Efficacy Questionnaire","Confidence to function despite pain"]],
  recent:["Self-determination theory is increasingly used to design exercise adherence programmes in rehabilitation."],
  mnemonic:{word:"NDIR", items:[["N","Need - lack"],["D","Drive - push"],["I","Incentive - pull"],["R","Reinforcement - repeat"]], extra:"Maslow from bottom: Please Save Love, Earn Self-respect (Physiological, Safety, Love, Esteem, Self-actualisation)."},
  example:"A 55-year-old farmer in Erode after knee replacement is not doing exercises. When the physiotherapist sets a goal of walking to his field in six weeks and charts his knee flexion each week, he starts exercising regularly.",
  flags:["Lack of motivation may be depression: screen and refer","Over-arousal and anxiety reduce performance (Yerkes-Dodson)","Punishment and scolding reduce motivation and trust"],
  viva:[["Differentiate drive and incentive.","Drive pushes from inside; incentive pulls from outside."],["Top of Maslow's hierarchy?","Self-actualisation."],["Give two primary needs.","Hunger and thirst (also sleep, oxygen, pain avoidance)."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Motivation."},{c:"Maslow AH. A theory of human motivation. Psychological Review. 1943;50:370-396.", q:"Maslow theory of human motivation 1943"},{c:"Levack WMM, Weatherall M, Hay-Smith EJC, et al. Goal setting and strategies to enhance goal pursuit for adults with acquired disability participating in rehabilitation. Cochrane Database Syst Rev. 2015.", q:"Levack goal setting rehabilitation Cochrane"}],
  keywords:"motivation motive drive incentive reinforcement need maslow hierarchy primary secondary intrinsic extrinsic yerkes dodson",
  mcq:[["Which is a primary (biological) motive?",["Achievement","Thirst","Affiliation","Power"],1,"Thirst is unlearned and biological."],["In Maslow's hierarchy, which need lies just above physiological needs?",["Esteem","Belongingness","Safety","Self-actualisation"],2,"Safety needs come second."]]
},
{
  id:"ps-emotions", title:"Emotions: physiology (RAS, hypothalamus, limbic system), theories; anger, fear and anxiety", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["emotion physiology","James Lange theory","Cannon Bard theory","reticular activating system","hypothalamus emotion","fear anger anxiety","limbic system"],
  simple:"An emotion is a strong feeling, like fear or anger, that comes with body changes such as a fast heartbeat and sweating. The hypothalamus, limbic system and reticular activating system in the brain produce these feelings and body changes. Patients often feel fear and anxiety about pain and movement, and this changes how they do in physiotherapy.",
  flow:["Stimulus is perceived and appraised by the brain","Limbic system and amygdala colour it with feeling","Hypothalamus triggers autonomic and hormonal changes","RAS raises arousal and alertness","Body shows signs: heart rate, sweating, muscle tension","Feeling is expressed as fear, anger or anxiety"],
  exam:[
    {h:"Definition and features", p:["Emotion: a complex state of feeling with physiological arousal, subjective experience and expressive behaviour (Morgan and King).","Features: aroused by a stimulus, involves body changes, has a feeling tone (pleasant or unpleasant), shows in face and voice, and is short-lived compared to mood.","Basic emotions (Ekman): happiness, sadness, fear, anger, surprise, disgust."]},
    {h:"Physiology of emotion", p:["Hypothalamus: controls autonomic and endocrine responses; sympathetic activation (fight or flight) and HPA axis (cortisol); stimulation can produce rage (sham rage in animals).","Limbic system (Papez circuit): amygdala for fear and threat detection, hippocampus for emotional memory, cingulate gyrus; prefrontal cortex regulates and controls emotion.","Reticular activating system (RAS): brainstem network that controls arousal and alertness; activation theory (Lindsley) says emotion depends on RAS arousal.","Body changes: tachycardia, raised BP, rapid breathing, dilated pupils, sweating, dry mouth, raised blood sugar, muscle tension, altered GSR."]},
    {h:"Theories of emotion", p:["James-Lange: body changes come first and our feeling is the perception of them ('we feel afraid because we tremble').","Cannon-Bard: thalamus sends signals at the same time to cortex (feeling) and to body (arousal).","Schachter-Singer two-factor: arousal plus cognitive label gives the emotion. Lazarus: cognitive appraisal decides the emotion."]},
    {h:"Fear, anger and anxiety", p:["Fear: response to a real, present danger; leads to flight or freezing; in patients fear of pain or re-injury causes guarding and avoidance (fear-avoidance model).","Anger: response to frustration or injustice; raised muscle tone and aggression; seen in patients after sudden disability.","Anxiety: diffuse, future-oriented apprehension without a clear object; palpitations, restlessness, poor sleep, muscle tension; can become anxiety disorder."]},
    {h:"Relevance to physiotherapy", p:["Fear and anxiety raise pain perception and muscle guarding; explanation, graded exposure and relaxation help.","Relaxation techniques (Jacobson progressive relaxation, diaphragmatic breathing) reduce arousal.","Emotional lability after stroke or head injury; anger after SCI or amputation; therapist should respond calmly and empathetically.","Moderate arousal improves performance; very high anxiety impairs learning of exercises."]},
    {h:"Conclusion", p:["Emotions have a brain and body basis; recognising and calming fear, anger and anxiety improves pain, learning and recovery."]}
  ],
  tip:"Draw a sagittal brain with RAS in brainstem, hypothalamus below thalamus and amygdala in temporal lobe, with arrows to heart, lungs and sweat glands via the sympathetic chain.",
  evidence:[["Pain education and graded exposure for fear of movement","Reduce kinesiophobia and disability in chronic back pain","Moderate"],["Progressive muscle relaxation","Reduces anxiety in several patient groups","Low-moderate"]],
  evidenceSource:"Vlaeyen and Linton fear-avoidance model (Pain 2000); Guyton and Hall, limbic system chapter",
  outcomes:[["Tampa Scale of Kinesiophobia","Fear of movement"],["GAD-7 or HADS anxiety","Anxiety level"],["Fear-Avoidance Beliefs Questionnaire","Fear beliefs about activity and work"]],
  recent:["Pain neuroscience education is widely used to reduce threat appraisal in people with chronic pain."],
  mnemonic:{word:"HRAL", items:[["H","Hypothalamus - autonomic and hormones"],["R","RAS - arousal"],["A","Amygdala - fear"],["L","Limbic cortex - feeling and memory"]], extra:"James-Lange: body first; Cannon-Bard: both together; Schachter: arousal plus label."},
  example:"A 40-year-old woman in Coimbatore with a healed wrist fracture shakes and sweats when asked to bear weight on her hand. The physiotherapist explains healing, uses breathing to calm her and starts graded weight bearing on a table.",
  flags:["Panic attack features may mimic cardiac events: rule out medical causes","Anger with threats of harm: ensure safety and inform team","Persistent anxiety or low mood: refer to psychologist"],
  viva:[["Which part of the brain detects fear?","The amygdala."],["What does the RAS do in emotion?","Controls general arousal and alertness."],["Differentiate fear and anxiety.","Fear has a present, specific object; anxiety is diffuse and about the future."]],
  refs:[{b:"guyton",ch:"Behavioural and motivational mechanisms of the brain: limbic system and hypothalamus"},{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Emotions."},{c:"Vlaeyen JWS, Linton SJ. Fear-avoidance and its consequences in chronic musculoskeletal pain: a state of the art. Pain. 2000;85:317-332.", q:"Vlaeyen Linton fear-avoidance state of the art"}],
  keywords:"emotion physiology hypothalamus limbic amygdala reticular activating system james lange cannon bard fear anger anxiety",
  mcq:[["'We feel afraid because we tremble' summarises which theory?",["Cannon-Bard","James-Lange","Schachter-Singer","Lazarus"],1,"James-Lange puts body change before feeling."],["Arousal and alertness are mainly controlled by the:",["Cerebellum","Basal ganglia","Reticular activating system","Hippocampus"],2,"The RAS in the brainstem controls arousal."]]
},
{
  id:"ps-personality", title:"Personality: definition, Freud's id, ego and superego, types and assessment (inventories and projective tests)", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["Freud personality structure","id ego superego","defence mechanisms","personality inventories MMPI","projective tests Rorschach TAT","type A type B personality","trait theory"],
  simple:"Personality is a person's typical way of thinking, feeling and behaving that makes them unique. Freud said personality has three parts: the id that wants pleasure, the superego that is the conscience, and the ego that balances them with reality. Psychologists measure personality using questionnaires and projective tests like inkblots.",
  flow:["Personality: unique, stable pattern of behaviour and thought","Freud: id, ego and superego in constant tension","Defence mechanisms protect the ego from anxiety","Type and trait theories describe personality dimensions","Inventories measure traits by questionnaire","Projective tests reveal hidden motives through ambiguous stimuli"],
  exam:[
    {h:"Definition", p:["Personality is the dynamic organisation within the individual of the psychophysical systems that determine his characteristic behaviour and thought (Allport).","Determinants: heredity, physique and endocrine factors, family, culture, social and educational experiences."]},
    {h:"Freud's psychoanalytic theory", p:["Levels of mind: conscious, preconscious and unconscious (iceberg model; most of the mind is unconscious).","Id: inborn, unconscious, works on the pleasure principle, seeks immediate satisfaction of drives (libido, aggression).","Ego: develops from id, works on the reality principle, mediates between id, superego and the outside world. Superego: conscience and ego ideal, internalised parental and social morals.","Defence mechanisms of the ego: repression, denial, projection, rationalisation, regression, displacement, sublimation, reaction formation. Psychosexual stages: oral, anal, phallic, latency, genital."]},
    {h:"Type and trait theories", p:["Type theories: Hippocrates (sanguine, choleric, melancholic, phlegmatic), Kretschmer and Sheldon body types (endomorph, mesomorph, ectomorph), Jung (introvert, extrovert), Type A (hurried, competitive, linked to heart disease) and Type B (relaxed).","Trait theories: Allport (cardinal, central, secondary traits), Cattell (16 source traits), Eysenck (extraversion, neuroticism, psychoticism), Big Five (openness, conscientiousness, extraversion, agreeableness, neuroticism)."]},
    {h:"Assessment: inventories", p:["Self-report questionnaires that are objective and easily scored.","MMPI (Minnesota Multiphasic Personality Inventory): clinical scales for psychopathology.","Cattell's 16 PF, Eysenck Personality Questionnaire, NEO-PI for Big Five. Other methods: interview, rating scales, behavioural observation, situational tests."]},
    {h:"Assessment: projective tests", p:["Ambiguous stimuli onto which the person projects unconscious needs and conflicts.","Rorschach inkblot test: 10 cards of inkblots (5 black and grey, 5 with colour). TAT (Thematic Apperception Test, Murray and Morgan): pictures; the person tells a story.","Sentence completion, word association and draw-a-person tests; CAT for children. Limitation: subjective scoring and lower reliability."]},
    {h:"Relevance to physiotherapy", p:["Personality affects pain coping, adherence and recovery; an anxious, high-neuroticism patient needs more reassurance.","Recognise defence mechanisms such as denial after amputation or SCI, regression in hospital and displacement of anger onto staff.","Type A patients in cardiac rehab need stress management alongside exercise."]},
    {h:"Conclusion", p:["Freud's model, trait theories and tests help us understand why patients with the same diagnosis behave very differently in rehab."]}
  ],
  tip:"Draw Freud's iceberg: small tip above water (conscious), waterline band (preconscious), large submerged part (unconscious) with id deep down, ego spanning all levels and superego partly above and below.",
  evidence:[["Personality traits such as neuroticism","Associated with higher pain-related disability and distress","Moderate (observational)"],["Stress management in cardiac rehabilitation","May improve psychological outcomes","Low-moderate"]],
  evidenceSource:"Morgan and King, Introduction to Psychology; observational studies of personality and chronic pain",
  outcomes:[["Eysenck Personality Questionnaire","Extraversion and neuroticism"],["Coping Strategies Questionnaire","How patients cope with pain"]],
  recent:["The Big Five model has become the most widely used research framework for personality."],
  mnemonic:{word:"PRIDE", items:[["P","Projection"],["R","Repression, Regression, Rationalisation"],["I","Intellectualisation"],["D","Denial, Displacement"],["E","Ego protects itself"]], extra:"Id = I want it now; Ego = Let us be realistic; Superego = That is wrong."},
  example:"A 28-year-old man in Madurai with paraplegia after a road accident shouts at the physiotherapist every morning; the team recognises displacement of anger about his injury and responds calmly while keeping therapy going.",
  flags:["Projective tests must only be given and interpreted by trained psychologists","Do not label patients by personality type; behaviour changes with illness"],
  viva:[["Which part of personality follows the reality principle?","The ego."],["How many cards in Rorschach test?","Ten inkblot cards."],["Name one personality inventory.","MMPI (also 16 PF, EPQ)."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Personality."},{c:"Mangal SK. General Psychology. Sterling Publishers. Chapter: Personality and its assessment."},{b:"hurlock",ch:"Personality development"}],
  keywords:"personality freud id ego superego defence mechanisms type trait mmpi 16pf rorschach tat projective inventory",
  mcq:[["The pleasure principle governs the:",["Ego","Superego","Id","Preconscious"],2,"The id seeks immediate gratification."],["Which is a projective test?",["MMPI","16 PF","Thematic Apperception Test","Eysenck Personality Questionnaire"],2,"TAT uses ambiguous pictures to elicit stories."]]
},
{
  id:"ps-learning-theories", title:"Learning: Thorndike's laws, classical and operant conditioning", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["theories of learning","trial and error learning","Pavlov classical conditioning","Skinner operant conditioning","laws of learning","insight learning","reinforcement schedules"],
  simple:"Learning is a lasting change in behaviour that comes from practice or experience. Thorndike showed learning by trial and error, Pavlov showed that a signal can come to trigger a response (classical conditioning), and Skinner showed that rewarded behaviour is repeated (operant conditioning). Physiotherapists use these ideas to teach exercises, change pain behaviour and train new movements.",
  flow:["Learning: lasting behaviour change from experience","Thorndike: trial and error; laws of readiness, exercise, effect","Pavlov: neutral bell paired with food gives conditioned salivation","Skinner: behaviour followed by reward is repeated","Reinforcement, extinction, generalisation and discrimination shape learning","Physio applies them to exercise teaching and behaviour change"],
  exam:[
    {h:"Definition", p:["Learning is a relatively permanent change in behaviour or potential behaviour that results from practice or experience, not from maturation, fatigue or drugs."]},
    {h:"Thorndike's trial and error learning", p:["Experiment: hungry cat in a puzzle box learned to press a lever to get out and reach food; time to escape fell gradually over trials.","Law of readiness: learning is satisfying when the learner is ready. Law of exercise: use strengthens and disuse weakens a connection.","Law of effect: responses followed by satisfaction are strengthened; those followed by discomfort are weakened (basis of reinforcement)."]},
    {h:"Classical conditioning (Pavlov)", p:["Unconditioned stimulus (food) gives unconditioned response (salivation); a neutral stimulus (bell) paired repeatedly with food becomes a conditioned stimulus producing conditioned response (salivation to bell).","Extinction: CS repeatedly presented without UCS, the response fades; spontaneous recovery after rest.","Generalisation (similar stimuli also produce response) and discrimination; higher-order conditioning. Watson's Little Albert showed fear can be conditioned."]},
    {h:"Operant conditioning (Skinner)", p:["Skinner box: rat presses a lever and receives food; behaviour is controlled by its consequences.","Positive reinforcement adds a pleasant stimulus; negative reinforcement removes an unpleasant one; both increase behaviour. Punishment decreases behaviour.","Schedules: continuous; fixed ratio, variable ratio, fixed interval, variable interval; variable ratio is most resistant to extinction. Shaping: rewarding successive approximations."]},
    {h:"Other theories", p:["Insight learning (Kohler): chimpanzee Sultan joined sticks to reach banana; sudden grasp of relations.","Observational learning (Bandura): learning by watching a model; attention, retention, reproduction, motivation."]},
    {h:"Application in physiotherapy", p:["Law of exercise: repetition of correct movement; law of effect: praise and visible progress.","Shaping: reward small steps in gait or hand function (as in constraint-induced movement therapy).","Classical conditioning explains fear of the physio room or anticipatory pain; operant model (Fordyce) explains pain behaviours maintained by attention, treated by reinforcing activity (graded activity).","Modelling: patients learn from watching the therapist or other patients in group classes."]},
    {h:"Conclusion", p:["Conditioning principles are the backbone of exercise teaching and behaviour change in rehabilitation."]}
  ],
  tip:"Draw Pavlov's three-phase table: before (bell = no response, food = salivation), during (bell + food = salivation), after (bell = salivation), with UCS, UCR, CS and CR labels.",
  evidence:[["Operant graded activity for chronic low back pain","Similar benefit to other active exercise approaches; better than minimal care","Moderate"],["Shaping in constraint-induced movement therapy after stroke","Improves arm use","Moderate"]],
  evidenceSource:"Fordyce operant model of pain; Cochrane reviews of behavioural treatment for chronic low back pain and of CIMT",
  outcomes:[["Activity diary","Change in activity behaviour"],["Motor Activity Log","Real-life arm use after CIMT"]],
  recent:["Behavioural graded activity and graded exposure are recommended elements of active management for persistent back pain."],
  mnemonic:{word:"REE", items:[["R","Readiness"],["E","Exercise"],["E","Effect"]], extra:"Pavlov = dog and bell (stimulus-stimulus); Skinner = rat and lever (response-consequence)."},
  example:"A child with hemiplegic CP in Chennai earns a sticker each time she reaches with her affected hand during play; over weeks the therapist only rewards higher and further reaches (shaping).",
  flags:["Avoid punishment-based methods with patients","Reinforcing pain behaviours (only giving attention when patient complains) can maintain disability"],
  viva:[["State Thorndike's law of effect.","Responses followed by satisfaction are strengthened; those followed by discomfort are weakened."],["Define extinction in classical conditioning.","Fading of CR when CS is repeatedly presented without UCS."],["Which schedule is most resistant to extinction?","Variable ratio."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Learning."},{c:"Mangal SK. General Psychology. Sterling Publishers. Chapter: Learning and theories of learning."},{c:"Fordyce WE. Behavioral Methods for Chronic Pain and Illness. St Louis: Mosby; 1976."}],
  keywords:"learning thorndike trial error laws readiness exercise effect pavlov classical conditioning skinner operant reinforcement shaping kohler bandura",
  mcq:[["In Pavlov's experiment, salivation to the bell after conditioning is the:",["Unconditioned response","Conditioned stimulus","Conditioned response","Unconditioned stimulus"],2,"A learned response to the CS is the CR."],["Removing an unpleasant stimulus to increase a behaviour is:",["Punishment","Negative reinforcement","Extinction","Positive reinforcement"],1,"Negative reinforcement increases behaviour by removal of something aversive."]]
},
{
  id:"ps-effective-learning", title:"Effective ways of learning: massed vs spaced, whole vs part, mnemonics and other methods", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["economical methods of learning","massed and distributed practice","whole and part method","mnemonics","recitation method","SQ3R","overlearning"],
  simple:"Some ways of learning work better than others. Spreading study or practice over several short sessions (spaced) beats cramming it all at once (massed), and the right mix of whole and part practice depends on the task. Physiotherapists use the same rules when they teach patients new movements and home exercises.",
  flow:["Learning efficiency depends on how practice is organised","Spaced practice gives better long-term retention than massed","Whole method for short meaningful tasks; part for long complex ones","Recitation, feedback and overlearning strengthen memory","Mnemonics link new facts to easy cues","Physio applies these to motor learning and home programmes"],
  exam:[
    {h:"Introduction", p:["Economical (effective) methods of learning are ways of organising practice to learn faster and remember longer.","They apply to verbal material (studying for exams) and to motor skills (learning to walk with crutches)."]},
    {h:"Massed vs spaced (distributed) practice", p:["Massed: continuous practice without rest (cramming). Spaced: practice divided into sessions with rest intervals.","Spaced practice gives better retention and less fatigue and boredom; supported by a large research base (spacing effect, first shown by Ebbinghaus).","Massed practice may suit short, simple tasks or when warm-up is important; for physical skills, too much massing causes fatigue and poor technique."]},
    {h:"Whole vs part method", p:["Whole: the entire material or skill practised as one unit; keeps meaning and flow. Part: divided into sections learned separately and then joined.","Whole suits short, meaningful, well-integrated tasks and more able learners; part suits long, complex tasks and young or slow learners.","Progressive part method (learn part 1, then 1+2, then 1+2+3) combines advantages; in motor learning, part practice works for serial tasks but highly continuous tasks such as gait are best practised whole."]},
    {h:"Mnemonics and other aids", p:["Mnemonics: memory aids such as acronyms (SOAP), rhymes, method of loci (placing items along a familiar route), keyword and peg word methods, chunking.","Recitation (self-testing): recalling material without looking is better than re-reading (testing effect).","SQ3R: survey, question, read, recite, review. Meaningful learning, overlearning (practice beyond first mastery), knowledge of results and feedback, motivation and good sleep."]},
    {h:"Application in physiotherapy", p:["Give short, frequent exercise sessions (for example 3 times daily) instead of one long session.","Break complex tasks (sit to stand, transfers) into parts, then link them; practise whole gait in real settings.","Use mnemonics and picture sheets for home programmes; ask patients to demonstrate back (teach-back) rather than just watch.","Use variable and random practice for better retention and transfer (contextual interference)."]},
    {h:"Application for students", p:["Plan revision in spaced sessions across weeks before university exams; self-test with MCQs and viva questions.","Use mnemonics for nerve supply and muscle attachments; draw diagrams from memory."]},
    {h:"Conclusion", p:["Organising practice wisely makes learning faster and memory longer for both students and patients."]}
  ],
  tip:"Draw two bar diagrams over time: one tall single block (massed) and several small blocks with gaps (spaced), with a retention curve that stays higher after spaced practice.",
  evidence:[["Spaced vs massed practice for verbal learning","Better long-term retention with spacing","High"],["Practice testing (recall) vs re-reading","Better retention","High"],["Random vs blocked practice in motor learning","Often better retention and transfer, but evidence in patients is mixed","Low-moderate"]],
  evidenceSource:"Cepeda et al., Psychological Bulletin 2006 (distributed practice meta-analysis); Dunlosky et al., Psychological Science in the Public Interest 2013",
  outcomes:[["Retention test","Skill or recall after a delay"],["Teach-back","Patient's correct demonstration of home exercises"]],
  recent:["Learning science reviews rate practice testing and distributed practice as the most useful study techniques."],
  mnemonic:{word:"SWiM", items:[["S","Spaced beats massed"],["W","Whole for short meaningful, part for long complex"],["M","Mnemonics and self-testing"]], extra:"Progressive part = 1, 1+2, 1+2+3."},
  example:"A 70-year-old man in Vellore learning to use a walker is taught sit to stand in parts (scoot forward, feet back, lean, push up) and then practises the whole transfer five times, three times a day.",
  flags:["Fatigue during massed practice increases fall risk in frail patients","Cognitively impaired patients need simple, consistent instructions and caregiver involvement"],
  viva:[["Which is better for retention: massed or spaced?","Spaced (distributed) practice."],["What is the progressive part method?","Learning parts cumulatively: 1, then 1+2, then 1+2+3."],["What is overlearning?","Practice beyond the point of first mastery to strengthen retention."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Memory and learning."},{c:"Cepeda NJ, Pashler H, Vul E, Wixted JT, Rohrer D. Distributed practice in verbal recall tasks: a review and quantitative synthesis. Psychol Bull. 2006;132:354-380.", q:"Cepeda distributed practice verbal recall review"},{b:"shumway",ch:"Motor learning and recovery of function"}],
  keywords:"massed spaced distributed practice whole part method progressive part mnemonics recitation sq3r overlearning economical learning",
  mcq:[["For a long, complex task, which method usually works best for a slow learner?",["Whole method","Part method","Massed method","No practice"],1,"Long complex tasks are learned best in parts."],["Method of loci is a type of:",["Projective test","Mnemonic","Reinforcement schedule","Intelligence test"],1,"It places items along an imagined familiar route."]]
},
{
  id:"ps-thinking-creativity", title:"Thinking, reasoning, creativity and delusions", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["thinking process","types of thinking","reasoning deductive inductive","problem solving","creativity stages","delusion definition","disorders of thought"],
  simple:"Thinking is using ideas, symbols and concepts in the mind to solve problems and make decisions. Creativity is thinking in new and useful ways. A delusion is a fixed false belief that a person holds strongly even when shown it is untrue and that is not explained by culture; it is a sign of mental illness.",
  flow:["Thinking manipulates images, concepts and language","Reasoning: deductive from general, inductive from specifics","Problem solving: define, plan, test, evaluate","Creativity: divergent thinking through Wallas's four stages","Delusion: fixed false belief not shared by culture","Physio uses problem solving and spots abnormal beliefs"],
  exam:[
    {h:"Thinking: definition and elements", p:["Thinking is a cognitive process of mentally manipulating information (images, symbols, concepts, language) to form ideas, solve problems and make decisions.","Elements: images, concepts (mental categories), symbols and language, propositions."]},
    {h:"Types of thinking and reasoning", p:["Perceptual (concrete), conceptual (abstract), reflective, creative and critical thinking; autistic or fantasy thinking.","Convergent thinking: narrowing to one correct answer; divergent thinking: producing many possible answers (Guilford).","Deductive reasoning: from a general rule to a specific conclusion; inductive reasoning: from specific observations to a general rule.","Problem solving steps: identify, analyse, generate solutions, choose, implement, evaluate; hindered by mental set and functional fixedness; heuristics and algorithms."]},
    {h:"Creativity", p:["The ability to produce work that is both novel and useful.","Wallas's stages: preparation, incubation, illumination (insight), verification.","Features of creative people: curiosity, flexibility, originality, fluency, tolerance of ambiguity, persistence. Creativity is related to but different from intelligence."]},
    {h:"Delusions and disorders of thought", p:["Delusion: a false, firmly held belief, not corrected by reasoning or evidence, and out of keeping with the person's cultural and educational background.","Types: persecutory, grandiose, reference, jealousy, nihilistic, somatic (hypochondriacal), guilt, control (passivity).","Seen in schizophrenia, delusional disorder, mania, psychotic depression, dementia and delirium.","Other thought disorders: flight of ideas, thought block, loosening of association; obsessions differ from delusions because insight is present."]},
    {h:"Relevance to physiotherapy", p:["Clinical reasoning (hypothetico-deductive and pattern recognition) is the physiotherapist's thinking skill for diagnosis and treatment planning.","Creative problem solving: designing low-cost aids and home exercises with local materials.","Recognising delusions (for example a patient believing staff are poisoning him) or somatic delusions so the patient can be referred to psychiatry; do not argue with the delusion.","Distinguish delusion from culturally shared beliefs (for example evil eye beliefs are not delusions)."]},
    {h:"Conclusion", p:["Good thinking and creativity make a better clinician, while recognising delusions protects the patient by early psychiatric referral."]}
  ],
  tip:"Draw Wallas's four creativity stages as a staircase, and beside it a box defining delusion with three key words: false, fixed, not culturally shared.",
  evidence:[["Teaching structured clinical reasoning to physiotherapy students","Improves reasoning performance in education studies","Low"],["Antipsychotic treatment for delusions in psychosis","Reduces psychotic symptoms","High"]],
  evidenceSource:"Morgan and King, Introduction to Psychology; Ahuja, A Short Textbook of Psychiatry",
  outcomes:[["Mental status examination","Thought content and form"],["Clinical reasoning rubrics","Quality of student reasoning"]],
  recent:["Clinical reasoning frameworks in physiotherapy now include both analytic and pattern-recognition thinking."],
  mnemonic:{word:"PIIV", items:[["P","Preparation"],["I","Incubation"],["I","Illumination"],["V","Verification"]], extra:"Delusion = FFNC: False, Fixed, Not Culturally shared."},
  example:"A 65-year-old man in a Chennai hospital refuses walking practice because he believes nurses are secretly mixing poison in his IV fluid. The physiotherapist does not argue, reports it, and the psychiatrist diagnoses delirium.",
  flags:["New-onset delusions in an older inpatient: think delirium (infection, drugs, metabolic causes)","Delusions with command to harm: urgent psychiatric help","Never argue with or reinforce a delusion"],
  viva:[["Define delusion.","A false, fixed belief not corrected by evidence and not in keeping with the person's culture."],["Name Wallas's four stages.","Preparation, incubation, illumination, verification."],["Differentiate convergent and divergent thinking.","Convergent finds one correct answer; divergent generates many possibilities."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Thinking and language."},{c:"Ahuja N. A Short Textbook of Psychiatry. Jaypee. Chapter: Signs and symptoms in psychiatry."},{c:"Mangal SK. General Psychology. Sterling Publishers. Chapter: Thinking, reasoning and creativity."}],
  keywords:"thinking reasoning deductive inductive problem solving creativity wallas divergent convergent delusion thought disorder",
  mcq:[["A belief that is false, fixed and not shared by one's culture is a:",["Hallucination","Illusion","Delusion","Obsession"],2,"This is the definition of a delusion."],["Insight (illumination) in creativity follows which stage?",["Verification","Incubation","Preparation","Evaluation"],1,"Wallas: preparation, incubation, illumination, verification."]]
},
{
  id:"ps-frustration-conflict", title:"Frustration and conflict: sources, types of conflict and reactions", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["frustration","types of conflict","approach avoidance conflict","Lewin conflicts","frustration aggression hypothesis","defence mechanisms","adjustment"],
  simple:"Frustration is the feeling we get when something blocks us from reaching a goal. Conflict happens when we must choose between two or more goals or options that pull us in different directions. Patients feel both: a man with a stroke is frustrated that he cannot walk, and may be in conflict between wanting to go home and fearing he will fall.",
  flow:["Goal-directed behaviour is blocked by a barrier","Frustration: feeling of being blocked","Sources: environment, personal limits, conflicting motives","Conflicts: approach-approach, avoidance-avoidance, approach-avoidance, double","Reactions: aggression, withdrawal, regression or defence mechanisms","Constructive coping and clear goals reduce frustration in rehab"],
  exam:[
    {h:"Definitions", p:["Frustration: the blocking of goal-directed behaviour, and the emotional state that results.","Conflict: a state in which a person faces two or more incompatible motives, goals or choices at the same time."]},
    {h:"Sources of frustration", p:["Environmental: physical barriers (stairs for a wheelchair user), social and economic barriers, rules, delays.","Personal: physical disability, illness, lack of ability, unrealistic aims.","Conflict between motives is itself a major source of frustration."]},
    {h:"Types of conflict (Lewin and Miller)", p:["Approach-approach: two desirable goals (choose between two good colleges); easiest to resolve.","Avoidance-avoidance: two undesirable options (painful exercise or stiff joint); person may try to escape both.","Approach-avoidance: one goal with both attractive and unattractive aspects (surgery may relieve pain but is risky); causes vacillation.","Double approach-avoidance: two goals each with good and bad aspects (stay at hospital for therapy vs go home to family but less therapy)."]},
    {h:"Reactions to frustration", p:["Direct (constructive): increased effort, change of method, substitute goal, problem solving.","Aggression: frustration-aggression hypothesis (Dollard and colleagues, 1939); can be direct or displaced onto others.","Withdrawal, apathy, regression (childish behaviour), fixation, anxiety, psychosomatic complaints.","Defence mechanisms: rationalisation, projection, denial, sublimation, compensation."]},
    {h:"Relevance to physiotherapy", p:["Slow recovery, pain and loss of independence make patients frustrated; anger may be displaced onto therapist or family.","Set achievable short-term goals, show progress, give choices and explain reasons for each exercise.","Help patients resolve conflicts (for example about surgery or going home) with clear information and family meetings.","Therapists also face frustration (heavy caseload, slow progress); healthy coping prevents burnout."]},
    {h:"Conclusion", p:["Understanding frustration and conflict helps the physiotherapist respond to patient anger and indecision with patience and structured goal setting."]}
  ],
  tip:"Draw four small diagrams with a stick figure between plus (+) and minus (-) goals: + <- person -> +, - <- person -> -, person -> goal labelled +/-, and two +/- goals on either side.",
  evidence:[["Goal setting and feedback in rehab","Improves engagement; may reduce frustration","Low-moderate"],["Psychological support after stroke","May improve mood and adjustment","Low-moderate"]],
  evidenceSource:"Morgan and King, Introduction to Psychology; Dollard et al., Frustration and Aggression (1939)",
  outcomes:[["HADS","Distress from frustration and conflict"],["Patient goal attainment","Progress that reduces frustration"]],
  recent:["Shared decision-making tools are used to help patients resolve approach-avoidance conflicts about treatment choices."],
  mnemonic:{word:"AAAD", items:[["A","Approach-approach"],["A","Avoidance-avoidance"],["A","Approach-avoidance"],["D","Double approach-avoidance"]], extra:"Frustration leads to AWARD: Aggression, Withdrawal, Apathy, Regression, Defence mechanisms."},
  example:"A 50-year-old driver in Madurai after below-knee amputation snaps at his physiotherapist when prosthetic training is slow. She sets weekly walking goals and shows him his progress chart, and his anger settles.",
  flags:["Aggression that threatens safety: involve the team","Withdrawal and hopelessness may signal depression or suicide risk"],
  viva:[["Which conflict is easiest to resolve?","Approach-approach."],["Who proposed frustration-aggression hypothesis?","Dollard and colleagues (1939)."],["Give an example of avoidance-avoidance conflict in rehab.","Choosing between painful exercise and a permanently stiff joint."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Frustration, conflict and stress."},{c:"Mangal SK. General Psychology. Sterling Publishers. Chapter: Frustration, conflict and adjustment."}],
  keywords:"frustration conflict approach avoidance lewin miller aggression defence mechanisms adjustment withdrawal regression",
  mcq:[["Choosing between two unpleasant options is a/an:",["Approach-approach conflict","Avoidance-avoidance conflict","Approach-avoidance conflict","Double approach conflict"],1,"Both options are undesirable."],["Shouting at the physiotherapist because of anger about one's injury is:",["Sublimation","Displacement","Rationalisation","Compensation"],1,"Anger is shifted to a safer target."]]
},
{
  id:"ps-sensation-perception", title:"Sensation, attention and perception; illusion and hallucination", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["sensation and perception","attention determinants","Gestalt laws of perception","illusion vs hallucination","perceptual constancy","sensory threshold","phantom limb"],
  simple:"Sensation is the raw information our sense organs pick up, like light or pressure. Attention picks which information to focus on, and perception is the brain giving meaning to it. An illusion is a wrong perception of something real, while a hallucination is a perception without anything really being there.",
  flow:["Receptors detect stimulus and convert it to nerve impulses","Sensation reaches the cortex: raw experience","Attention selects some stimuli and filters others","Perception organises and interprets them (Gestalt laws)","Illusion: misperception of a real stimulus","Hallucination: perception without any external stimulus"],
  exam:[
    {h:"Sensation", p:["Sensation: the detection of a stimulus by a sense organ and its transmission to the brain; the raw first stage.","Senses: vision, hearing, smell, taste, touch, pain, temperature, proprioception (kinaesthesia) and vestibular (balance).","Absolute threshold: minimum stimulus detected 50 percent of the time; difference threshold (just noticeable difference) follows Weber's law; sensory adaptation to constant stimuli."]},
    {h:"Attention", p:["Attention: focusing consciousness on some stimuli while ignoring others.","Types: selective, sustained, divided and alternating attention.","External determinants: intensity, size, contrast, change, movement, novelty, repetition. Internal determinants: interest, motives, needs, mental set, emotional state.","Span of attention is limited; fatigue, pain and anxiety reduce attention."]},
    {h:"Perception", p:["Perception: the process of organising and interpreting sensations to give them meaning; influenced by past experience, expectation and culture.","Gestalt principles: figure-ground, proximity, similarity, closure, continuity.","Perceptual constancies (size, shape, colour, brightness); depth perception using binocular (retinal disparity) and monocular cues."]},
    {h:"Illusion and hallucination", p:["Illusion: misinterpretation of a real external stimulus; can occur in normal people (Muller-Lyer lines, moon illusion, rope seen as snake in the dark).","Hallucination: perception without an external stimulus, experienced as real; auditory (commonest in schizophrenia), visual (delirium, alcohol withdrawal), tactile, olfactory, gustatory.","Pseudo-hallucinations; hypnagogic and hypnopompic hallucinations at sleep onset or waking can be normal."]},
    {h:"Relevance to physiotherapy", p:["Sensory assessment (touch, pain, proprioception) is basic to neuro examination; impaired sensation is a contraindication for many electrotherapy and heat modalities.","Perceptual problems after stroke: unilateral neglect, body scheme disorders, pusher syndrome, visual field loss; treated with scanning training and mirror therapy.","Phantom limb sensation and phantom pain after amputation; mirror therapy and graded motor imagery.","Use attention principles: reduce distractions, use bright cues and movement, short focused sessions."]},
    {h:"Conclusion", p:["Sensation feeds perception through the filter of attention; disorders at any level change how patients move and learn."]}
  ],
  tip:"Draw a left-to-right flow chart: Stimulus, Receptor, Sensation, Attention filter (funnel), Perception (meaning); add Muller-Lyer arrows to illustrate illusion.",
  evidence:[["Mirror therapy for phantom limb pain","Some short-term pain reduction","Low"],["Visual scanning training for neglect after stroke","Improves neglect test scores; effect on function uncertain","Low"]],
  evidenceSource:"Cochrane reviews of interventions for neglect after stroke; Morgan and King, Introduction to Psychology",
  outcomes:[["Line bisection and star cancellation tests","Unilateral neglect"],["Nottingham Sensory Assessment","Sensory loss after stroke"]],
  recent:["Graded motor imagery (laterality recognition, imagined movement, mirror therapy) is used for phantom limb pain and CRPS."],
  mnemonic:{word:"SAP", items:[["S","Sensation - receive"],["A","Attention - select"],["P","Perception - interpret"]], extra:"Illusion = real object, wrong meaning; Hallucination = no object at all."},
  example:"A 62-year-old woman in Thanjavur after right hemisphere stroke eats only from the right side of her plate and bumps into the left door frame. The physiotherapist uses bright tape on the left and scanning training (neglect).",
  flags:["New visual hallucinations in an older patient: suspect delirium","Absent sensation: avoid heat, ice and electrical modalities in that area","Command hallucinations: urgent psychiatric referral"],
  viva:[["Define illusion.","Misinterpretation of a real external stimulus."],["Most common hallucination in schizophrenia?","Auditory hallucination."],["Name two Gestalt laws.","Proximity and similarity (also closure, continuity, figure-ground)."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Sensory processes and perception."},{b:"guyton",ch:"Sensory receptors and somatic sensations"},{b:"osullivan",ch:"Examination of sensory function"}],
  keywords:"sensation attention perception gestalt threshold weber illusion hallucination neglect phantom limb",
  mcq:[["Seeing a rope as a snake in dim light is an example of:",["Hallucination","Delusion","Illusion","Agnosia"],2,"A real stimulus is misinterpreted."],["Which is an internal determinant of attention?",["Intensity","Movement","Interest","Contrast"],2,"Interest arises from within the person."]]
},
{
  id:"ps-leadership", title:"Leadership: definition, qualities, styles and theories", subject:"Psychology and sociology", region:"General psychology", stages:"steps",
  aliases:["leadership qualities","leadership styles","autocratic democratic laissez faire","trait theory of leadership","transformational leadership","qualities of a good leader"],
  simple:"Leadership is the ability to guide and influence a group towards a common goal. Good leaders communicate well, are honest, make decisions and care about their team. Physiotherapists lead patients, students, therapy groups and departments, so leadership skills matter from the first year.",
  flow:["Leader influences a group towards shared goals","Qualities: vision, integrity, communication, empathy, decision making","Styles: autocratic, democratic, laissez-faire","Theories: trait, behavioural, situational, transformational","Style is matched to the situation and team","Physio leads patients, groups, students and departments"],
  exam:[
    {h:"Definition", p:["Leadership is the process of influencing the activities of an individual or group towards achieving a goal in a given situation.","Leader differs from manager: a leader inspires and sets direction; a manager plans, organises and controls (good professionals do both)."]},
    {h:"Qualities of a good leader", p:["Personal: integrity and honesty, self-confidence, emotional stability, intelligence, initiative, enthusiasm, physical and mental fitness.","Interpersonal: good communication and listening, empathy, fairness, ability to motivate and develop others, conflict resolution.","Task-related: vision, planning, decision making, responsibility, knowledge and competence, adaptability and accountability."]},
    {h:"Styles of leadership (Lewin)", p:["Autocratic (authoritarian): leader decides alone; quick decisions in emergencies but low morale and creativity.","Democratic (participative): group shares decisions; higher satisfaction and commitment; slower.","Laissez-faire (free rein): leader gives little direction; works only with highly skilled, motivated teams.","Others: bureaucratic, paternalistic, servant leadership."]},
    {h:"Theories of leadership", p:["Great man and trait theories: leaders are born with certain traits.","Behavioural theories: task-oriented vs people-oriented leadership (Ohio and Michigan studies).","Situational and contingency theories (Fiedler; Hersey and Blanchard): best style depends on the situation and followers' readiness.","Transactional (rewards for performance) vs transformational leadership (inspires vision, intellectual stimulation, individual consideration)."]},
    {h:"Leadership in physiotherapy", p:["Leading the patient: guiding and motivating through rehab with a coaching style.","Leading group exercise classes (cardiac rehab, antenatal, back school) and community-based rehabilitation camps.","Clinical teaching of students and interns, heading physiotherapy departments, advocacy for disability rights.","Working in the multidisciplinary team: sharing leadership, respecting other professionals."]},
    {h:"Conclusion", p:["Leadership is a learnable skill; a flexible, democratic and transformational approach suits health care teams best in most situations."]}
  ],
  tip:"Draw a horizontal line labelled 'leader control' on the left to 'group freedom' on the right, marking autocratic, democratic and laissez-faire along it.",
  evidence:[["Transformational leadership in health care teams","Associated with higher staff satisfaction and lower burnout","Low-moderate (observational)"],["Leadership training for health professionals","Improves self-reported leadership behaviours","Low"]],
  evidenceSource:"Lewin, Lippitt and White studies of leadership styles; systematic reviews of nursing and allied health leadership",
  outcomes:[["Multifactor Leadership Questionnaire","Transformational and transactional leadership style"],["Staff satisfaction surveys","Team climate"]],
  recent:["Clinical leadership is now included in many physiotherapy curricula and professional development frameworks."],
  mnemonic:{word:"LEADER", items:[["L","Listens"],["E","Empathy and ethics"],["A","Accountable"],["D","Decisive"],["E","Encourages team"],["R","Role model"]], extra:"Styles = ADL: Autocratic, Democratic, Laissez-faire."},
  example:"A senior physiotherapist in a Puducherry district hospital holds weekly team meetings where juniors suggest changes to the stroke exercise group (democratic style), but takes quick charge when a patient collapses in the gym (autocratic style).",
  flags:["Autocratic leadership used all the time causes poor morale and errors going unreported","Laissez-faire leadership with inexperienced staff risks patient safety"],
  viva:[["Name three leadership styles by Lewin.","Autocratic, democratic and laissez-faire."],["What is transformational leadership?","Leadership that inspires a shared vision and develops followers beyond self-interest."],["When is autocratic style useful?","In emergencies needing quick decisions."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Social psychology and group processes."},{c:"Basavanthappa BT. Nursing Administration. Jaypee. Chapter: Leadership."},{c:"Rao CN Shankar. Sociology: Principles of Sociology with an Introduction to Social Thought. S Chand. Chapter: Social groups and leadership."}],
  keywords:"leadership qualities styles autocratic democratic laissez faire trait situational transformational transactional",
  mcq:[["In which style does the group share decision making?",["Autocratic","Laissez-faire","Democratic","Bureaucratic"],2,"Democratic leadership is participative."],["Situational leadership theory was described by:",["Hersey and Blanchard","Freud","Pavlov","Maslow"],0,"They linked style to follower readiness."]]
},
{
  id:"ps-patient-reactions", title:"Psychological reactions of patients during admission and treatment", subject:"Psychology and sociology", region:"Health psychology", stages:"steps",
  aliases:["reactions to hospitalisation","patient psychology","sick role reaction","hospital anxiety","regression in hospital","emotional reactions to illness","admission stress"],
  simple:"Being admitted to hospital is frightening: patients lose privacy, independence and their normal roles, and they worry about pain, money and the future. Common reactions are anxiety, fear, denial, anger, depression, regression and dependence. A physiotherapist who expects these reactions can explain, reassure and involve the patient so treatment goes better.",
  flow:["Illness and admission threaten body, role and future","Strange place, loss of privacy and control","Reactions: anxiety, fear, denial, anger, depression","Regression and dependency or non-cooperation","Staff explain, reassure and involve the patient","Adjustment allows active participation in rehab"],
  exam:[
    {h:"Introduction", p:["Hospital admission is a stressful life event; illness threatens body integrity, independence, finances, family roles and future plans.","Reaction depends on the illness, personality, age, past experience, social support, culture and the way staff behave."]},
    {h:"Stresses of hospitalisation", p:["Unfamiliar environment, noise, loss of privacy, strange routines and food.","Separation from family; loss of control and decision making; loss of work and income.","Fear of pain, procedures, surgery, disability and death; lack of information; medical jargon."]},
    {h:"Common psychological reactions", p:["Anxiety and fear: most common; restlessness, sleeplessness, many questions or silence.","Denial: refusing to accept seriousness, may skip treatment; anger and hostility directed at staff or family.","Depression and grief, especially with loss of a body part or function; guilt and shame.","Regression and excessive dependency (childlike behaviour, demanding help with tasks they can do); sometimes over-independence and refusing help; non-compliance; hospital-induced confusion (delirium) in older patients; children show separation anxiety."]},
    {h:"Reactions during treatment", p:["Fear of pain with exercise or mobilisation; fear of falling on first standing; anxiety about electrical modalities.","Over-expectation of quick cure or a 'magic machine'; disappointment when progress is slow.","Positive reactions: hope, motivation and trust when progress is visible."]},
    {h:"Role of the physiotherapist", p:["Introduce yourself, explain each procedure in simple local language, get consent and allow questions.","Respect privacy and dignity (screens, draping); give the patient choices and control.","Encourage independence: avoid doing for the patient what he can do himself; praise effort.","Involve family; watch for depression or delirium and inform the team; refer for counselling when needed."]},
    {h:"Conclusion", p:["Expecting and gently managing psychological reactions reduces anxiety, improves cooperation and speeds functional recovery."]}
  ],
  tip:"Draw a central figure 'patient on admission' with arrows outward to the reactions: anxiety, fear, denial, anger, depression, regression, dependency.",
  evidence:[["Preoperative education before joint replacement","May reduce anxiety; little effect on function","Low-moderate"],["Early mobilisation and orientation in older inpatients","Helps prevent delirium as part of multicomponent programmes","Moderate"]],
  evidenceSource:"Cochrane review of preoperative education for hip or knee replacement (McDonald et al., 2014); multicomponent delirium prevention studies",
  outcomes:[["HADS","Anxiety and depression in hospital"],["Confusion Assessment Method","Delirium screening"]],
  recent:["Hospital elder-life and delirium prevention programmes include early mobilisation as a key component."],
  mnemonic:{word:"FADDR", items:[["F","Fear and anxiety"],["A","Anger"],["D","Denial"],["D","Depression and dependency"],["R","Regression"]], extra:"Respond with EASE: Explain, Allow questions, Show respect, Encourage independence."},
  example:"A 45-year-old mill worker in Tiruppur admitted for a spinal fracture keeps asking for the bedpan and refuses to roll himself, though he can. The physiotherapist explains log rolling, praises each attempt and slowly reduces help.",
  flags:["Sudden confusion in an older inpatient: delirium, inform doctor","Expressed hopelessness or wish to die: inform team urgently","Child separated from parent showing despair or withdrawal"],
  viva:[["Most common reaction on admission?","Anxiety and fear."],["What is regression in a patient?","Return to childlike, more dependent behaviour under stress."],["How can the physio reduce admission anxiety?","Explain procedures, give choices, respect privacy and involve family."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Health psychology."},{c:"Indrani TK. Textbook of Sociology for Nurses. Jaypee. Chapter: Hospital as a social system and the patient."},{c:"McDonald S, Page MJ, Beringer K, Wasiak J, Sprowson A. Preoperative education for hip or knee replacement. Cochrane Database Syst Rev. 2014.", q:"McDonald preoperative education hip knee replacement Cochrane"}],
  keywords:"patient reactions hospitalisation admission anxiety fear denial anger depression regression dependency delirium",
  mcq:[["A patient who can feed himself but insists on being fed in hospital shows:",["Sublimation","Regression","Projection","Rationalisation"],1,"Regression is return to more dependent, childlike behaviour."],["Which action best reduces admission anxiety?",["Using technical terms","Explaining procedures simply and allowing questions","Avoiding talking to family","Doing everything for the patient"],1,"Clear information gives control and reduces fear."]]
},
{
  id:"ps-loss-bereavement", title:"Reaction to loss, death and bereavement", subject:"Psychology and sociology", region:"Health psychology", stages:"steps",
  aliases:["grief","Kubler-Ross stages","stages of dying","bereavement","mourning","loss of limb grief","prolonged grief disorder"],
  simple:"Loss can be death of a loved one, but also loss of a limb, a job, or the ability to walk. People go through grief, often with phases like shock, denial, anger, bargaining, depression and acceptance, though not in a fixed order. Physiotherapists meet grief in amputees, people with spinal cord injury and families of dying patients, and must respond with empathy.",
  flow:["Loss: death, body part, function, role or hope","Shock and denial in the first phase","Anger, bargaining and sadness follow","Gradual acceptance and reorganisation of life","Phases overlap and may repeat; not a fixed ladder","Empathy, support and referral when grief is complicated"],
  exam:[
    {h:"Definitions", p:["Loss: being deprived of something valued (person, body part, function, role, possession).","Grief: the emotional response to loss. Bereavement: the state of having lost someone through death. Mourning: the social and cultural expression of grief (rituals)."]},
    {h:"Kubler-Ross stages (dying and loss)", p:["Denial ('This cannot be happening').","Anger ('Why me?') often directed at family, doctors or God.","Bargaining (promises to God, seeking miracle cures).","Depression (sadness, withdrawal). Acceptance (calm, making arrangements).","Stages may overlap, come back or be skipped; they are a guide, not a rule (DABDA)."]},
    {h:"Other models and features of grief", p:["Bowlby and Parkes: numbness, yearning and searching, disorganisation and despair, reorganisation.","Worden's tasks of mourning: accept the reality, work through the pain, adjust to life without the deceased, find an enduring connection while moving on.","Normal grief features: sadness, crying, sleep and appetite changes, guilt, preoccupation; usually eases over months.","Complicated or prolonged grief: intense grief persisting long after the loss with marked impairment; risk factors include sudden or violent death, poor support, prior depression."]},
    {h:"Loss in physiotherapy patients", p:["Amputation: grief for the limb, altered body image, phantom limb; SCI: loss of walking, bladder, sexual function and work role.","Stroke, burns with disfigurement, progressive diseases (MND, DMD) and terminal cancer; families of these patients also grieve.","Grief stage affects rehab: denial may lead to unrealistic goals, depression to poor participation."]},
    {h:"Role of the physiotherapist", p:["Listen, acknowledge feelings, do not hurry or give false hope; use simple honest language.","Respect cultural and religious practices around death and mourning.","Palliative physiotherapy: comfort positioning, breathing, gentle mobility, maintain dignity and independence as long as possible.","Recognise complicated grief or depression and refer; take care of one's own emotions after patient deaths."]},
    {h:"Conclusion", p:["Grief is a normal process after any major loss; sensitive support helps patients and families move towards acceptance and engage in rehab."]}
  ],
  tip:"Draw a wave-shaped curve over time with labels Denial, Anger, Bargaining, Depression (lowest point) and Acceptance, and add a note that people move back and forth.",
  evidence:[["Routine grief counselling for normal grief","No clear benefit; normal grief usually resolves","Low"],["Targeted therapy for prolonged grief","Reduces grief symptoms","Moderate"]],
  evidenceSource:"Kubler-Ross, On Death and Dying (1969); DSM-5-TR prolonged grief disorder criteria",
  outcomes:[["HADS or PHQ-9","Depression during grief"],["Amputee Body Image Scale","Body image after limb loss"]],
  recent:["Prolonged grief disorder was added to ICD-11 and to DSM-5-TR (2022) as a diagnosis distinct from normal grief."],
  mnemonic:{word:"DABDA", items:[["D","Denial"],["A","Anger"],["B","Bargaining"],["D","Depression"],["A","Acceptance"]], extra:"Stages are a map, not a timetable."},
  example:"A 32-year-old construction worker in Hosur after above-knee amputation says he will walk normally in a month without a prosthesis and refuses stump care (denial). The physiotherapist listens, gives honest information and introduces him to a prosthesis user from a peer group.",
  flags:["Talk of suicide or no reason to live: urgent referral","Grief lasting many months with inability to function: prolonged grief or depression","Never promise full recovery to ease grief"],
  viva:[["Who described the five stages of dying?","Elisabeth Kubler-Ross (1969)."],["Differentiate grief and mourning.","Grief is the inner emotional response; mourning is its social and cultural expression."],["Give an example of non-death loss seen in physiotherapy.","Loss of a limb after amputation or loss of walking after SCI."]],
  refs:[{c:"Kubler-Ross E. On Death and Dying. New York: Macmillan; 1969."},{c:"Worden JW. Grief Counseling and Grief Therapy. Springer Publishing. Chapter: Tasks of mourning."},{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Health psychology."}],
  keywords:"loss grief bereavement mourning kubler ross denial anger bargaining depression acceptance prolonged grief amputation",
  mcq:[["Promising to God to give up smoking if allowed to recover belongs to which stage?",["Denial","Anger","Bargaining","Acceptance"],2,"Bargaining involves deals to postpone loss."],["The social and cultural expression of grief is:",["Bereavement","Mourning","Denial","Depression"],1,"Mourning refers to rituals and customs."]]
},
{
  id:"ps-stress-burnout", title:"Stress, psychosomatic disorders and professional burnout", subject:"Psychology and sociology", region:"Health psychology", stages:"012234",
  aliases:["stress general adaptation syndrome","Selye GAS","psychosomatic illness","burnout syndrome","stress management","coping","Maslach burnout"],
  simple:"Stress is the body's and mind's response when demands feel greater than our ability to cope. Long-lasting stress can cause or worsen physical illnesses called psychosomatic disorders, like hypertension, peptic ulcer or tension headache. Burnout is a type of work stress in which health workers become exhausted, detached from patients and feel they achieve little.",
  flow:["Stressor appraised as threat beyond coping resources","Sympathetic and HPA axis activation: adrenaline and cortisol","Alarm, resistance and exhaustion stages (Selye)","Chronic stress drives psychosomatic illness and burnout","Assess with stress, mood and burnout scales","Manage with coping skills, relaxation, exercise and support"],
  exam:[
    {h:"Definitions", p:["Stress: a state of physical and psychological strain that arises when demands are appraised as exceeding a person's resources (Lazarus and Folkman).","Stressor: the event that causes stress (physical, psychological, social). Eustress is positive stress; distress is harmful stress.","Psychosomatic disorder: a physical illness in which psychological factors play a significant part in onset or worsening."]},
    {h:"Sources and physiology of stress", p:["Sources: life events (Holmes and Rahe Social Readjustment Rating Scale; death of spouse ranks highest), daily hassles, frustration, conflict, work and exam pressure, illness and disability.","Selye's General Adaptation Syndrome: alarm (fight or flight), resistance (adaptation with high cortisol), exhaustion (resources depleted, illness).","Physiology: hypothalamus activates sympathetic system (adrenaline, raised heart rate, BP, glucose) and HPA axis (CRH, ACTH, cortisol); chronic cortisol suppresses immunity and raises BP and blood sugar."]},
    {h:"Effects and psychosomatic disorders", p:["Psychological: anxiety, irritability, poor concentration, sleep problems, depression; behavioural: smoking, alcohol, overeating.","Psychosomatic conditions: essential hypertension, coronary heart disease (Type A link), peptic ulcer, bronchial asthma, irritable bowel syndrome, tension headache and migraine, psoriasis, diabetes worsening.","Musculoskeletal: neck and shoulder muscle tension, worsening of chronic low back pain and fibromyalgia."]},
    {h:"Professional burnout", p:["A response to chronic work stress in helping professions; three dimensions (Maslach): emotional exhaustion, depersonalisation (cynicism, treating patients as objects) and reduced personal accomplishment.","Causes: high workload, long hours, lack of control, poor rewards, emotional demands, poor team support, value conflict.","Effects: absenteeism, errors, poor patient care, leaving the profession; measured with the Maslach Burnout Inventory."]},
    {h:"Management of stress", p:["Problem-focused coping (solve the cause) and emotion-focused coping (manage feelings); social support.","Relaxation: Jacobson's progressive muscular relaxation, Mitchell's physiological relaxation, diaphragmatic breathing, yoga and meditation.","Regular aerobic exercise (for example 150 minutes moderate activity per week), sleep hygiene, time management, counselling or CBT.","Burnout prevention: reasonable caseload, team support, supervision, breaks and leave, reflective practice, organisational change."]},
    {h:"Role of physiotherapist", p:["Teach relaxation and exercise to patients with hypertension, tension headache, anxiety and chronic pain.","Recognise stress worsening pain and fatigue; use biopsychosocial approach.","Protect own health: recognise early signs of burnout and seek support."]},
    {h:"Conclusion", p:["Stress affects every body system; relaxation, exercise and good work environments are practical tools the physiotherapist offers to patients and needs for himself."]}
  ],
  tip:"Draw Selye's GAS curve: resistance level on y-axis, time on x-axis; a dip (alarm), a raised plateau (resistance) and a fall (exhaustion).",
  evidence:[["Aerobic exercise for stress and anxiety symptoms","Reduces anxiety symptoms","Moderate"],["Progressive muscle relaxation","Reduces stress and anxiety in several populations","Low-moderate"],["Organisation-directed interventions for burnout","Small reductions in burnout","Low"]],
  evidenceSource:"Selye, The Stress of Life; Lazarus and Folkman, Stress, Appraisal and Coping (1984); Maslach Burnout Inventory manual",
  outcomes:[["Perceived Stress Scale","Self-rated stress"],["Maslach Burnout Inventory","Exhaustion, depersonalisation, accomplishment"],["Blood pressure","Physiological stress marker"]],
  recent:["WHO's ICD-11 describes burn-out as an occupational phenomenon resulting from unmanaged chronic workplace stress, not as a medical condition."],
  mnemonic:{word:"ARE", items:[["A","Alarm"],["R","Resistance"],["E","Exhaustion"]], extra:"Burnout = EDR: Exhaustion, Depersonalisation, Reduced accomplishment."},
  example:"A 26-year-old physiotherapist in a busy Chennai private hospital treating 30 patients a day feels drained, becomes curt with patients and doubts her skills. With her senior she reduces the caseload, takes leave and starts regular exercise.",
  flags:["Chest pain, palpitations or very high BP should not be assumed to be stress: rule out cardiac cause","Suicidal ideation in stressed patients or staff: urgent help","Substance misuse used to cope with stress"],
  viva:[["Name the stages of GAS.","Alarm, resistance and exhaustion."],["Three dimensions of burnout?","Emotional exhaustion, depersonalisation and reduced personal accomplishment."],["Give two psychosomatic disorders.","Essential hypertension and peptic ulcer (also asthma, IBS, tension headache)."]],
  refs:[{c:"Holmes TH, Rahe RH. The Social Readjustment Rating Scale. J Psychosom Res. 1967;11:213-218.", q:"Holmes Rahe Social Readjustment Rating Scale"},{c:"Maslach C, Leiter MP. Understanding the burnout experience: recent research and its implications for psychiatry. World Psychiatry. 2016;15:103-111.", q:"Maslach Leiter understanding the burnout experience World Psychiatry"},{b:"guyton",ch:"Adrenocortical hormones: cortisol and stress"},{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Stress and coping."}],
  keywords:"stress selye general adaptation syndrome cortisol psychosomatic hypertension peptic ulcer burnout maslach relaxation coping",
  mcq:[["Which stage of GAS follows alarm?",["Exhaustion","Resistance","Recovery","Denial"],1,"Alarm, resistance, exhaustion."],["Depersonalisation in burnout refers to:",["Loss of memory","Cynical, detached attitude to patients","Feeling of unreality about oneself only","Physical tiredness"],1,"Maslach describes it as treating clients as objects."]]
},
{
  id:"ps-communication-counselling", title:"Communication and counselling in physiotherapy", subject:"Psychology and sociology", region:"Health psychology", stages:"steps",
  aliases:["communication process","verbal and non verbal communication","barriers to communication","counselling skills","active listening","breaking bad news SPIKES","therapeutic relationship"],
  simple:"Communication is sharing information, ideas and feelings between people through words, tone and body language. Counselling is a helping relationship where a trained person helps another understand their problem and make their own decisions. Good communication and counselling help patients trust the physiotherapist, understand their condition and stick to their exercises.",
  flow:["Sender encodes message and chooses channel","Receiver decodes; feedback closes the loop","Verbal and non-verbal parts must match","Remove barriers: language, noise, jargon, emotions","Counselling: rapport, listening, exploring, action plan","Patient understands, trusts and follows the plan"],
  exam:[
    {h:"Communication: definition and process", p:["Communication is the two-way process of exchanging information, thoughts and feelings to reach mutual understanding.","Elements: sender, message, encoding, channel (oral, written, gesture), receiver, decoding, feedback, context.","Types: verbal (spoken, written) and non-verbal (facial expression, eye contact, posture, touch, gestures, tone, personal space); one-way vs two-way."]},
    {h:"Barriers to communication", p:["Physical: noise, distance, poor lighting; physiological: hearing loss, aphasia, pain, sedation.","Semantic: language differences, medical jargon; psychological: anxiety, anger, prejudice, poor listening.","Cultural and social: gender norms, status gap between therapist and patient, literacy level."]},
    {h:"Effective communication skills", p:["Active listening: attention, nodding, paraphrasing, summarising; Egan's SOLER (Sit squarely, Open posture, Lean forward, Eye contact, Relaxed).","Open and closed questions; simple local language; check understanding by teach-back; empathy statements.","For special groups: aphasia (short sentences, gestures, pictures), hearing loss (face the patient, speak clearly, do not shout), children (play), elderly (slow, respectful).","Breaking bad news: SPIKES protocol (Setting, Perception, Invitation, Knowledge, Emotions with empathy, Strategy and summary)."]},
    {h:"Counselling", p:["Definition: a professional relationship in which a counsellor helps a person explore feelings and problems and find his own solutions.","Rogers' core conditions: empathy, unconditional positive regard, genuineness (congruence). Approaches: directive, non-directive (client-centred), eclectic.","Steps: build rapport, explore the problem, understand and set goals, plan action, follow up and terminate.","Principles: confidentiality, acceptance, non-judgemental attitude, respect for autonomy, no advice-giving by force."]},
    {h:"Counselling in physiotherapy", p:["Explaining diagnosis and prognosis; ergonomic and lifestyle advice; exercise adherence counselling (motivational interviewing).","Family counselling for children with CP, SCI and stroke; vocational and sexual health concerns after SCI with referral as needed.","Pre and post-operative counselling; know limits and refer to psychologists or psychiatrists."]},
    {h:"Conclusion", p:["Clear, empathetic communication and basic counselling skills are as important as manual skills in producing good physiotherapy outcomes."]}
  ],
  tip:"Draw the communication loop: Sender to Message to Channel to Receiver, with a curved Feedback arrow back to Sender and a 'Noise/Barriers' cloud on the channel.",
  evidence:[["Therapeutic alliance in physiotherapy","Associated with better pain and function outcomes","Low-moderate"],["Motivational interviewing for exercise adherence","Small to moderate improvements in adherence","Low-moderate"]],
  evidenceSource:"Baile et al., SPIKES, The Oncologist 2000; Rogers, Client-Centered Therapy (1951)",
  outcomes:[["Working Alliance Inventory","Strength of therapist-patient relationship"],["Teach-back accuracy","Patient understanding"],["Patient satisfaction questionnaires","Quality of communication"]],
  recent:["Telerehabilitation since 2020 has made video-call communication skills part of routine physiotherapy practice."],
  mnemonic:{word:"SOLER", items:[["S","Sit squarely"],["O","Open posture"],["L","Lean slightly forward"],["E","Eye contact"],["R","Relaxed"]], extra:"Counselling core conditions: EUG - Empathy, Unconditional positive regard, Genuineness."},
  example:"A Tamil-speaking grandmother in Kanchipuram with knee OA nods but does not do her exercises. The physiotherapist switches from English terms to Tamil, demonstrates each exercise, asks her to show it back and draws pictures for the home sheet.",
  flags:["Confidentiality: do not discuss patients in public areas or social media","Recognise when counselling needs exceed your training (suicidal thoughts, abuse): refer","Never give bad news in a corridor or without privacy"],
  viva:[["What is SOLER?","Egan's guide to attentive body posture: Sit squarely, Open posture, Lean forward, Eye contact, Relaxed."],["Name Rogers' core conditions.","Empathy, unconditional positive regard and genuineness."],["What does SPIKES stand for?","Setting, Perception, Invitation, Knowledge, Emotions, Strategy and summary."]],
  refs:[{c:"Baile WF, Buckman R, Lenzi R, Glober G, Beale EA, Kudelka AP. SPIKES: a six-step protocol for delivering bad news. Oncologist. 2000;5:302-311.", q:"Baile SPIKES six-step protocol delivering bad news"},{c:"Egan G. The Skilled Helper. Brooks/Cole. Chapter: Attending and listening."},{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Psychotherapy and counselling."}],
  keywords:"communication process verbal non verbal barriers listening soler counselling rogers empathy spikes bad news motivational interviewing",
  mcq:[["Which is a non-verbal component of communication?",["Medical report","Eye contact","Telephone call","Written leaflet"],1,"Eye contact is body language."],["Client-centred counselling was developed by:",["Freud","Carl Rogers","Skinner","Pavlov"],1,"Rogers emphasised empathy and positive regard."]]
},
{
  id:"ps-compliance", title:"Compliance and non-compliance (adherence) in treatment", subject:"Psychology and sociology", region:"Health psychology", stages:"steps",
  aliases:["adherence to exercise","non compliance causes","patient compliance","home exercise adherence","health belief model","concordance"],
  simple:"Compliance means how well a patient follows the advice given, such as taking medicines or doing home exercises. Many patients do not fully follow their exercise programmes because of pain, forgetfulness, poor understanding, cost or low motivation. The newer word adherence stresses that the patient and therapist agree on the plan together.",
  flow:["Therapist and patient agree a treatment plan","Barriers: patient, condition, therapy, system, social factors","Non-compliance: missed sessions, skipped exercises, wrong technique","Assess with diaries, apps, questioning and checking technique","Improve with simple plans, education, feedback, family support","Better adherence gives better outcomes"],
  exam:[
    {h:"Definitions", p:["Compliance: the extent to which a patient's behaviour coincides with medical or health advice (implies obeying).","Adherence: the extent to which behaviour corresponds with recommendations agreed with the health worker (WHO 2003); concordance stresses partnership.","Non-compliance can be intentional (deciding not to) or unintentional (forgetting, not understanding)."]},
    {h:"Factors affecting adherence (WHO five dimensions)", p:["Socio-economic: poverty, distance to clinic, transport cost, loss of daily wages, illiteracy, lack of family support.","Health system and therapist: poor communication, short sessions, long waiting times, no follow-up.","Condition-related: chronic disease with no symptoms, severity, depression, cognitive impairment.","Therapy-related: complex or long programmes, painful exercises, slow visible benefit, side effects. Patient-related: beliefs, low self-efficacy, fear, forgetfulness, low motivation."]},
    {h:"Theories explaining adherence", p:["Health Belief Model: perceived susceptibility, perceived severity, perceived benefits, perceived barriers, cues to action and self-efficacy.","Transtheoretical (stages of change) model: precontemplation, contemplation, preparation, action, maintenance.","Social cognitive theory (self-efficacy); operant reinforcement."]},
    {h:"Assessing adherence", p:["Self-report and exercise diaries; attendance records; checking exercise technique at each visit.","Apps, pedometers and wearable activity trackers; caregiver reports."]},
    {h:"Strategies to improve adherence", p:["Keep programmes short and simple (2-4 key exercises), linked to daily routines (for example during TV serial or after prayer).","Clear education with written or picture sheets in the local language; teach-back; explain why each exercise matters.","Agree goals together; give feedback on progress; positive reinforcement; reminders by phone or WhatsApp.","Involve family; address pain and fear; motivational interviewing; regular follow-up; group classes for peer support."]},
    {h:"Conclusion", p:["Non-adherence is common and is the hidden reason many physiotherapy programmes fail; it is prevented by partnership, simplicity and follow-up."]}
  ],
  tip:"Draw a pentagon with WHO's five adherence dimensions at the corners and the patient in the centre; add three strategy arrows: Simplify, Educate, Follow-up.",
  evidence:[["Behaviour change techniques (goal setting, feedback, reminders) for exercise adherence","Improve adherence modestly","Low-moderate"],["Written and illustrated home exercise instructions","Better recall and adherence than verbal advice alone","Low"]],
  evidenceSource:"WHO. Adherence to Long-Term Therapies: Evidence for Action (2003); Cochrane review of interventions to improve adherence to exercise for chronic musculoskeletal pain (Jordan et al., 2010)",
  outcomes:[["Exercise diary","Days and sets completed"],["Exercise Adherence Rating Scale","Home exercise adherence"],["Attendance rate","Clinic session adherence"]],
  recent:["Mobile apps and WhatsApp reminders with exercise videos are widely used to support home exercise adherence."],
  mnemonic:{word:"SPACE", items:[["S","Simple programme"],["P","Partnership in goal setting"],["A","Address barriers (pain, fear, cost)"],["C","Clear written or picture instructions"],["E","Encourage with feedback and follow-up"]], extra:"WHO 5 dimensions: Social, System, Condition, Therapy, Patient."},
  example:"A 38-year-old daily-wage worker in Villupuram with frozen shoulder stops coming after three visits because he loses a day's wage each time. The physiotherapist switches to a simple home programme with a WhatsApp video and fortnightly reviews.",
  flags:["Sudden non-attendance may reflect depression, worsening illness or financial crisis","Wrong technique at home can cause injury: check every visit","Do not blame or shame non-adherent patients"],
  viva:[["Differentiate compliance and adherence.","Compliance implies obeying advice; adherence implies following a plan agreed together."],["Name components of the Health Belief Model.","Perceived susceptibility, severity, benefits, barriers, cues to action, self-efficacy."],["Give two strategies to improve exercise adherence.","Simplify the programme and give feedback with follow-up."]],
  refs:[{c:"World Health Organization. Adherence to Long-Term Therapies: Evidence for Action. Geneva: WHO; 2003.", u:"https://iris.who.int/handle/10665/42682"},{c:"Jordan JL, Holden MA, Mason EE, Foster NE. Interventions to improve adherence to exercise for chronic musculoskeletal pain in adults. Cochrane Database Syst Rev. 2010.", q:"Jordan Holden interventions adherence exercise chronic musculoskeletal pain Cochrane"},{b:"kisner",ch:"Adherence to exercise and patient education"}],
  keywords:"compliance adherence non compliance health belief model stages of change home exercise programme barriers strategies",
  mcq:[["According to WHO, the term that implies agreement between patient and provider is:",["Compliance","Adherence","Obedience","Conformity"],1,"Adherence emphasises agreed recommendations."],["'Perceived barriers' is a component of which model?",["Maslow hierarchy","Health Belief Model","General Adaptation Syndrome","Kubler-Ross model"],1,"HBM includes perceived barriers and benefits."]]
},
{
  id:"ps-geriatric-paediatric", title:"Geriatric and paediatric psychology in physiotherapy", subject:"Psychology and sociology", region:"Health psychology", stages:"steps",
  aliases:["psychology of the elderly","child psychology hospital","separation anxiety","fear of falling","dementia and depression in elderly","play in therapy","old age problems"],
  simple:"Children and older people think, feel and react differently from young adults. Children fear separation from parents and learn best through play, while older adults may face loneliness, depression, memory problems and fear of falling. Physiotherapists must adapt how they communicate, motivate and treat at each end of life.",
  flow:["Children: developing thinking, fear of strangers and pain","Hospitalised child: protest, despair, detachment (Bowlby)","Use play, parents, praise and short sessions","Older adults: loss, loneliness, slower learning, fear of falling","Screen for depression, dementia and delirium","Respect, simple steps and independence goals for elderly"],
  exam:[
    {h:"Paediatric psychology: features", p:["Thinking depends on Piaget's stage: young children are concrete and egocentric, cannot understand long explanations.","Separation anxiety peaks around 8 months to 3 years; hospitalised children show protest, despair and detachment (Robertson and Bowlby).","Fear of pain, needles and strangers; regression (bed wetting, thumb sucking); temper tantrums; parents' anxiety passes to the child."]},
    {h:"Physiotherapy approach to children", p:["Treat with parent present; build rapport through play; use toys, games, songs and colourful equipment.","Short sessions with breaks; praise and small rewards; never lie about pain ('this will not hurt').","Give choices ('which leg first?'); use modelling by other children; involve school and family; family-centred care.","Adolescents: respect privacy and autonomy, address body image and peer concerns."]},
    {h:"Geriatric psychology: features", p:["Cognitive: slower processing and reaction time, some decline in recent memory; crystallised knowledge preserved. Dementia and delirium are common but not normal ageing.","Emotional: loneliness, losses (spouse, friends, income, role), depression (often presents as fatigue, poor appetite, pain), anxiety, fear of falling and dependency.","Social: retirement, changing joint family, elder neglect or abuse, financial dependence; Erikson integrity vs despair."]},
    {h:"Physiotherapy approach to older adults", p:["Address respectfully (not as a child); check hearing and vision; speak slowly, one instruction at a time; demonstrate and repeat.","Set functional goals that preserve independence and dignity (toileting, walking to temple, playing with grandchildren).","Treat fear of falling with balance training, graded confidence building and education.","Screen mood and cognition (GDS, MMSE or Mini-Cog) and refer; involve caregivers; group exercise reduces loneliness."]},
    {h:"Common points", p:["Both groups depend on caregivers; communication must include the family.","Both need safety, patience, praise and functional, meaningful activities."]},
    {h:"Conclusion", p:["Matching approach to age-related psychology turns a frightened child or a withdrawn elder into an active participant in therapy."]}
  ],
  tip:"Make a two-column table: Child (separation anxiety, play, parent present, short sessions) vs Elderly (loss, depression, fear of falling, slow clear instructions).",
  evidence:[["Balance and strength exercise programmes","Reduce falls and fear of falling in older adults","High (falls), moderate (fear)"],["Exercise for depression in older adults","Reduces depressive symptoms","Moderate"],["Family-centred care for children with disability","Improves parent satisfaction and child outcomes","Moderate"]],
  evidenceSource:"Sherrington et al., Cochrane 2019 exercise for falls prevention; Robertson and Bowlby studies on children in hospital",
  outcomes:[["Geriatric Depression Scale","Depression in older adults"],["Falls Efficacy Scale International","Fear of falling"],["FLACC or Wong-Baker faces","Pain in children"]],
  recent:["India's National Programme for Health Care of the Elderly (NPHCE) supports geriatric clinics and rehabilitation units at district hospitals."],
  mnemonic:{word:"PLAY and RESPECT", items:[["PLAY","Parents present, Let child choose, Avoid lies, Yes to praise"],["RESPECT","Repeat slowly, Explain one step, Safety, Preserve independence, Encourage, Check mood and cognition, Treat fear of falling"]], extra:"Bowlby's hospital stages: Protest, Despair, Detachment."},
  example:"An 80-year-old widow in Kumbakonam who fell at home now refuses to walk outside. The physiotherapist starts chair-based balance work, then walks with her to the temple gate, and links her to a senior citizens' exercise group.",
  flags:["Sudden confusion in elderly: delirium (medical emergency)","Unexplained injuries in child or elder: consider abuse","Depression with weight loss or suicidal talk in older adults"],
  viva:[["Stages of reaction of a hospitalised child?","Protest, despair, detachment."],["How does depression often present in the elderly?","With fatigue, poor appetite, sleep problems and vague pain rather than sadness."],["Name a scale for fear of falling.","Falls Efficacy Scale International (FES-I)."]],
  refs:[{b:"hurlock",ch:"Old age: physical and psychological changes"},{b:"berk",ch:"Emotional and social development in early childhood"},{b:"tecklin",ch:"The child and family in paediatric physical therapy"},{c:"Bowlby J. Attachment and Loss. Vol 2: Separation. London: Hogarth Press; 1973."}],
  keywords:"geriatric psychology paediatric psychology separation anxiety bowlby play elderly depression dementia fear of falling",
  mcq:[["The first stage of a young child's reaction to hospital separation is:",["Detachment","Despair","Protest","Acceptance"],2,"Protest (crying, searching) comes first."],["Which is preserved best in normal ageing?",["Reaction time","Processing speed","Crystallised intelligence","Recent memory"],2,"Accumulated knowledge is well maintained."]]
},
{
  id:"ps-behaviour-modification", title:"Behaviour modification: principles and techniques", subject:"Psychology and sociology", region:"Health psychology", stages:"steps",
  aliases:["behaviour therapy","token economy","shaping and chaining","systematic desensitisation","ABC analysis","operant pain management","behaviour change techniques"],
  simple:"Behaviour modification is the planned use of learning principles to increase helpful behaviours and reduce harmful ones. It uses tools such as rewards, shaping small steps, tokens and gradual exposure to feared situations. Physiotherapists use it to build exercise habits, reduce pain behaviour and teach children with disability new skills.",
  flow:["Define target behaviour clearly and measurably","ABC analysis: Antecedent, Behaviour, Consequence","Record baseline frequency","Apply technique: reinforcement, shaping, tokens, desensitisation","Monitor progress and fade rewards gradually","Generalise and maintain new behaviour at home"],
  exam:[
    {h:"Definition and basis", p:["Behaviour modification is the systematic application of learning principles (classical and operant conditioning, observational learning) to change observable behaviour.","Focuses on present observable behaviour, measurable goals and environmental control rather than inner causes."]},
    {h:"Steps", p:["Identify and define the target behaviour (for example 'walks 20 m with walker').","ABC (functional) analysis: antecedents that trigger, the behaviour, consequences that maintain it.","Measure baseline, set goals, choose technique, implement, record, evaluate, fade and generalise."]},
    {h:"Techniques to increase behaviour", p:["Positive reinforcement (praise, rewards); negative reinforcement.","Shaping: rewarding successive approximations to the target.","Chaining: forward or backward linking of steps (backward chaining for dressing).","Prompting and fading; modelling; token economy (tokens exchanged for rewards); contingency contracts; Premack principle (preferred activity follows less preferred one)."]},
    {h:"Techniques to decrease behaviour", p:["Extinction (withdrawing reinforcement, for example ignoring excessive pain behaviour while rewarding activity).","Time-out; response cost; differential reinforcement of other behaviour; mild punishment (used sparingly and ethically).","Systematic desensitisation (Wolpe): relaxation plus graded hierarchy of feared situations; flooding; aversion therapy (rarely used); biofeedback for muscle tension."]},
    {h:"Applications in physiotherapy", p:["Operant treatment of chronic pain (Fordyce): reinforce activity and well behaviour, quota-based graded activity rather than pain-contingent rest.","Graded exposure for fear of movement; graded activity for chronic fatigue and back pain.","Children with CP, autism or intellectual disability: shaping, chaining, token charts, praise for therapy cooperation.","Lifestyle change: weight loss, smoking cessation, physical activity using goal setting, self-monitoring and rewards; EMG biofeedback for muscle re-education."]},
    {h:"Limitations and ethics", p:["Must respect dignity and consent; avoid punishment-based methods; involve family for consistency.","Gains may not generalise without practice in real settings."]},
    {h:"Conclusion", p:["Behaviour modification gives the physiotherapist structured, measurable tools to build lasting healthy habits and function."]}
  ],
  tip:"Draw the ABC chain as three boxes: Antecedent, Behaviour, Consequence, with an arrow from Consequence looping back to show it controls future Behaviour.",
  evidence:[["Graded activity (operant) for chronic low back pain","Reduces disability compared to minimal care, similar to other exercise","Moderate"],["Graded exposure for fear of movement","Reduces fear and disability in some patients","Low-moderate"],["Behaviour change techniques for physical activity","Small to moderate increases","Moderate"]],
  evidenceSource:"Fordyce, Behavioral Methods for Chronic Pain and Illness (1976); Wolpe, Psychotherapy by Reciprocal Inhibition (1958)",
  outcomes:[["Behaviour frequency chart","Change in target behaviour"],["Activity tracker or diary","Physical activity"],["Tampa Scale of Kinesiophobia","Fear after graded exposure"]],
  recent:["Behaviour change technique taxonomies (for example Michie's BCT taxonomy) are used to design and report physiotherapy exercise programmes."],
  mnemonic:{word:"ABC", items:[["A","Antecedent"],["B","Behaviour"],["C","Consequence"]], extra:"Increase: Reinforce, Shape, Chain, Token. Decrease: Extinction, Time-out, Desensitise."},
  example:"A 6-year-old boy with Down syndrome in Chennai refuses to climb stairs. The physiotherapist rewards one step with a star sticker, then two steps, then a full flight; five stars earn time on the swing.",
  flags:["Never use painful or humiliating punishment","Extinction of pain behaviour must not ignore new red-flag symptoms"],
  viva:[["What is shaping?","Reinforcing successive approximations to the target behaviour."],["Who developed systematic desensitisation?","Joseph Wolpe."],["What is a token economy?","A system where tokens earned for target behaviours are exchanged for rewards."]],
  refs:[{c:"Morgan CT, King RA, Weisz JR, Schopler J. Introduction to Psychology. Tata McGraw-Hill. Chapter: Behaviour therapy."},{c:"Fordyce WE. Behavioral Methods for Chronic Pain and Illness. St Louis: Mosby; 1976."},{c:"Michie S, Richardson M, Johnston M, et al. The behavior change technique taxonomy (v1) of 93 hierarchically clustered techniques. Ann Behav Med. 2013;46:81-95.", q:"Michie behavior change technique taxonomy v1 93"}],
  keywords:"behaviour modification abc analysis reinforcement shaping chaining token economy desensitisation wolpe extinction graded activity fordyce",
  mcq:[["Linking the steps of dressing starting from the last step is:",["Forward chaining","Backward chaining","Flooding","Time-out"],1,"Backward chaining teaches the final step first."],["Systematic desensitisation combines relaxation with:",["Punishment","Graded exposure hierarchy","Token rewards","Medication"],1,"Wolpe paired relaxation with graded feared stimuli."]]
},
{
  id:"ps-substance-abuse", title:"Substance abuse: smoking, alcoholism and drug addiction", subject:"Psychology and sociology", region:"Health psychology", stages:"012234",
  aliases:["substance use disorder","alcohol dependence","tobacco addiction","nicotine dependence","drug addiction","de-addiction","CAGE questionnaire"],
  simple:"Substance abuse is harmful use of tobacco, alcohol or drugs that damages health, family and work. With repeated use the person develops tolerance, craving and withdrawal symptoms, which is dependence. Physiotherapists see the effects, such as neuropathy, falls, lung disease and poor healing, and can give brief advice to quit.",
  flow:["Causes: peer pressure, stress, availability, genetics, culture","Repeated use causes tolerance, craving and dependence","Signs: withdrawal, neglect of duties, health damage","Assess: CAGE, AUDIT, Fagerstrom, history","Treat: detoxification, counselling, medicines, support groups","Physio: brief advice, exercise, treat complications"],
  exam:[
    {h:"Definitions", p:["Substance abuse (harmful use): repeated use of a psychoactive substance that causes physical, psychological or social harm.","Dependence: a cluster of features including craving, loss of control, tolerance, withdrawal, neglect of other interests and continued use despite harm. DSM-5 uses the term substance use disorder (mild, moderate, severe).","Tolerance: need for more substance for same effect; withdrawal: symptoms when stopping."]},
    {h:"Causes", p:["Biological: genetic vulnerability, brain reward pathway (dopamine).","Psychological: stress, curiosity, low self-esteem, depression, anxiety, personality traits.","Social: peer pressure, family use, easy availability, advertising, cultural acceptance, unemployment, poverty."]},
    {h:"Smoking and tobacco", p:["Nicotine is highly addictive; India has both smoking (cigarette, beedi) and smokeless tobacco (gutka, khaini, paan).","Effects: COPD, lung cancer, oral cancer (smokeless), coronary artery disease, stroke, peripheral vascular disease (Buerger's disease), osteoporosis, delayed fracture and wound healing.","Assessment: Fagerstrom test; brief intervention using 5 As (Ask, Advise, Assess, Assist, Arrange) and 5 Rs for unwilling smokers; nicotine replacement therapy."]},
    {h:"Alcoholism", p:["Effects: liver disease, gastritis, pancreatitis, cardiomyopathy, peripheral neuropathy, myopathy, cerebellar degeneration, Wernicke-Korsakoff syndrome, falls and fractures, family violence, road accidents.","Withdrawal: tremors, sweating, insomnia, seizures; delirium tremens (confusion, hallucinations) is an emergency.","Screening: CAGE (Cut down, Annoyed, Guilty, Eye-opener) and AUDIT."]},
    {h:"Drug addiction", p:["Opioids (heroin, brown sugar), cannabis, sedatives, inhalants (solvent sniffing in street children), stimulants.","Complications: overdose, infections (HIV, hepatitis from shared needles), crime, school dropout."]},
    {h:"Management and role of physiotherapist", p:["Medical: detoxification, medicines for withdrawal and relapse prevention; psychological: motivational interviewing, CBT, relapse prevention; social: Alcoholics Anonymous, family therapy, de-addiction centres.","Physio: ask about tobacco and alcohol use at every assessment; brief advice to quit; exercise to reduce craving and improve mood and fitness.","Treat complications: pulmonary rehab in COPD, balance and gait training in alcoholic neuropathy and cerebellar ataxia, cardiac rehab, falls prevention."]},
    {h:"Conclusion", p:["Substance abuse is a biopsychosocial problem; physiotherapists contribute by screening, brief advice and rehabilitation of its complications."]}
  ],
  tip:"Draw a vicious circle: Use, Pleasure (dopamine), Tolerance, More use, Dependence, Withdrawal on stopping, back to Use; label the 5 As next to it.",
  evidence:[["Brief advice to quit smoking by health professionals","Increases quit rates modestly","High"],["Exercise as an aid to smoking cessation","Insufficient evidence for long-term quit benefit","Low"],["Brief alcohol interventions in primary care","Reduce alcohol consumption","Moderate"]],
  evidenceSource:"Cochrane reviews of physician advice for smoking cessation and of exercise interventions for smoking cessation; WHO AUDIT manual",
  outcomes:[["Fagerstrom Test for Nicotine Dependence","Nicotine dependence"],["AUDIT or CAGE","Alcohol problems"],["Pack-years","Lifetime smoking exposure"]],
  recent:["India banned production and sale of electronic cigarettes under the Prohibition of Electronic Cigarettes Act, 2019."],
  mnemonic:{word:"CAGE", items:[["C","Ever felt you should Cut down?"],["A","Annoyed by criticism of drinking?"],["G","Guilty about drinking?"],["E","Eye-opener drink in the morning?"]], extra:"Two or more yes answers suggest an alcohol problem. Quit advice: 5 As - Ask, Advise, Assess, Assist, Arrange."},
  example:"A 48-year-old lorry driver in Namakkal referred for unsteady gait has burning feet and loss of ankle jerks; he drinks daily. The physiotherapist gives balance training, foot care advice, and brief advice to cut down, and the doctor refers him to a de-addiction centre.",
  flags:["Delirium tremens or withdrawal seizures: medical emergency","Smoking near oxygen cylinders: fire hazard","Intoxicated patient: unsafe for exercise or modalities"],
  viva:[["What does CAGE stand for?","Cut down, Annoyed, Guilty, Eye-opener."],["What are the 5 As of smoking cessation?","Ask, Advise, Assess, Assist, Arrange."],["Name two neurological complications of alcoholism.","Peripheral neuropathy and cerebellar degeneration (also Wernicke-Korsakoff)."]],
  refs:[{b:"park",ch:"Alcohol and drug dependence; tobacco"},{c:"Ahuja N. A Short Textbook of Psychiatry. Jaypee. Chapter: Psychoactive substance use disorders."},{c:"Stead LF, Buitrago D, Preciado N, et al. Physician advice for smoking cessation. Cochrane Database Syst Rev. 2013.", q:"Stead physician advice for smoking cessation Cochrane"}],
  keywords:"substance abuse dependence tolerance withdrawal smoking tobacco nicotine alcoholism cage audit drug addiction de-addiction 5 as",
  mcq:[["The 'E' in CAGE stands for:",["Exercise","Eye-opener","Euphoria","Evening drink"],1,"A morning drink to steady nerves suggests dependence."],["Need for more of a substance to get the same effect is called:",["Withdrawal","Tolerance","Relapse","Craving"],1,"That is the definition of tolerance."]]
}
,{
  id:"ps-sociology-intro", title:"Sociology: definition, scope and its application in physiotherapy", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["sociology definition","scope of sociology","medical sociology","sociology of health","importance of sociology to physiotherapist","Auguste Comte"],
  simple:"Sociology is the scientific study of society, social groups and how people relate to one another. Medical sociology looks at how society shapes health, illness and treatment. A physiotherapist needs it because a patient's family, job, income, caste, beliefs and community decide whether rehabilitation actually works at home.",
  flow:["Sociology studies society, groups and social relationships","Founded as a science by Auguste Comte, 1838","Key concepts: society, community, culture, institution, status, role","Medical sociology links society to health and illness","Physio uses it to understand patient's family, work and beliefs","Goal: holistic, community-based, culturally fitting rehabilitation"],
  exam:[
    {h:"Definition", p:["Sociology is the scientific study of human society, social groups, social relationships and social behaviour.","The term was coined by Auguste Comte (1838), called the father of sociology; Durkheim, Max Weber and Karl Marx shaped it further.","Medical (health) sociology studies social causes and consequences of health and illness and the organisation of health care."]},
    {h:"Basic concepts", p:["Society: a web of social relationships among people sharing a territory and culture; community: a group living in a locality with a sense of belonging.","Social institutions: family, marriage, religion, education, economy, state, health care.","Status (position a person holds, ascribed or achieved) and role (behaviour expected of that status); sick role and therapist role are examples."]},
    {h:"Scope and branches", p:["Specialist view (formal school, Simmel): studies forms of social relationships; synthetic view (Durkheim): studies society as a whole.","Branches: rural and urban sociology, sociology of family, industrial, medical, sociology of disability, criminology, social demography.","Methods: survey, interview, observation, case study, comparative and historical method."]},
    {h:"Application in physiotherapy", p:["Holistic assessment: social history (family support, occupation, income, housing, transport, toilet type, floor sitting habits) changes goals and home programme.","Understanding illness behaviour, sick role and cultural beliefs improves communication and compliance.","Community-based rehabilitation (CBR), home visits and camps need knowledge of village structure, leaders and local resources.","Disability is partly social: WHO ICF (2001) includes environmental and personal factors; the social model asks society to remove barriers.","Team work: therapist, doctor, social worker, family and community act as a social group with roles and norms."]},
    {h:"Sociology versus psychology", p:["Psychology studies the individual mind and behaviour; sociology studies groups, institutions and social structure.","Both combine in the biopsychosocial model (Engel, 1977) used in modern physiotherapy."]},
    {h:"Conclusion", p:["Sociology helps the physiotherapist see the patient as a member of a family and community, so that treatment is realistic, acceptable and sustainable."]}
  ],
  tip:"Draw three concentric circles: Patient (centre), Family, Community/Society; write ICF environmental factors in the outer ring and arrows to Participation.",
  evidence:[["Social support and survival","Stronger social relationships linked with lower mortality in a large meta-analysis","Moderate"],["Community-based rehabilitation programmes","Some benefit for function and participation; studies are low quality","Low"],["Biopsychosocial rehabilitation for chronic back pain","Better than usual care for pain and disability","Moderate"]],
  evidenceSource:"Holt-Lunstad J, Smith TB, Layton JB. PLoS Med 2010; WHO CBR Guidelines 2010; Cochrane review of multidisciplinary biopsychosocial rehabilitation for chronic low back pain (Kamper 2014)",
  outcomes:[["Social history checklist","Family, work, housing and income factors"],["WHO ICF participation domains","Social participation"],["WHODAS 2.0","Disability across life areas"]],
  recent:["The WHO Rehabilitation 2030 initiative (2017) calls for rehabilitation to be integrated into community and primary health care."],
  mnemonic:{word:"FISH", items:[["F","Family and home"],["I","Income and occupation"],["S","Society: caste, culture, beliefs"],["H","Health services access"]], extra:"Ask FISH in every social history before setting a home programme."},
  example:"A 55-year-old paddy farmer from Thanjavur after knee replacement cannot sit on the floor or use an Indian toilet. Knowing his home and work, the physiotherapist plans a raised commode, a stool for meals, and graded squatting goals for later.",
  flags:["Ignoring social history leads to unrealistic home programmes","Do not stereotype patients by caste, religion or income"],
  viva:[["Who coined the term sociology?","Auguste Comte, in 1838."],["Define status and role.","Status is a social position; role is the behaviour expected of that position."],["Which WHO framework includes environmental factors in disability?","ICF, 2001."]],
  refs:[{c:"Shankar Rao CN. Sociology: Principles of Sociology with an Introduction to Social Thought. S Chand. Chapter: Nature and scope of sociology."},{c:"Indrani TK. Textbook of Sociology for Nurses. Jaypee. Chapter: Introduction to sociology."},{b:"park",ch:"Medicine and social sciences"},{c:"World Health Organization. International Classification of Functioning, Disability and Health (ICF). Geneva: WHO; 2001."}],
  keywords:"sociology definition comte scope medical sociology status role institution community icf social model physiotherapy application",
  mcq:[["The father of sociology is:",["Max Weber","Auguste Comte","Karl Marx","Sigmund Freud"],1,"Comte coined the term in 1838."],["The behaviour expected of a person holding a social position is called:",["Status","Norm","Role","Value"],2,"Role is the dynamic aspect of status."]]
},
{
  id:"ps-sociology-health", title:"Sociology and health: social factors in health and perception of illness", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["social factors affecting health","social determinants of health","illness behaviour","sick role Parsons","disease illness sickness","perception of illness"],
  simple:"Health is shaped not only by germs and genes but by income, education, housing, work, gender and culture. These are the social determinants of health. People also differ in how they notice, explain and act on symptoms, called illness behaviour, so the same knee pain may bring one person to a clinic and keep another at home.",
  flow:["Health is physical, mental and social well-being (WHO)","Social determinants: income, education, housing, work, gender","They change exposure, access and outcome of disease","Illness behaviour: noticing, explaining and acting on symptoms","Sick role (Parsons): rights and duties of the sick","Physio tailors care to social factors and illness beliefs"],
  exam:[
    {h:"Definitions", p:["WHO (1948): health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity.","Disease: biological abnormality found by the doctor; illness: the person's own experience of feeling unwell; sickness: the social role and recognition of being ill.","Social determinants of health: conditions in which people are born, grow, live, work and age."]},
    {h:"Social factors affecting health", p:["Economic: poverty causes malnutrition, overcrowding, infection, late treatment and inability to buy aids or attend therapy.","Education and literacy: affect hygiene, health awareness and understanding of exercise instructions.","Occupation: agricultural, construction and IT work bring specific injuries and postural problems; loss of daily wage limits therapy attendance.","Housing, sanitation, water, transport and distance from hospital.","Gender: women may get later care and less rehabilitation; family, marital status, social support, urban or rural residence, religion, caste and customs."]},
    {h:"Perception of illness and illness behaviour", p:["Illness behaviour (Mechanic): the ways people monitor their bodies, define symptoms, take remedial action and use health services.","Influenced by visibility and seriousness of symptoms, interference with work, tolerance of pain, knowledge, cultural beliefs, cost and availability of care.","Lay referral system: family and elders decide first; many try home remedies, temples or traditional bone setters before a hospital.","Abnormal illness behaviour: denial, delay, or exaggeration and doctor shopping."]},
    {h:"Sick role (Talcott Parsons, 1951)", p:["Rights: exempted from normal duties; not blamed for being ill.","Duties: must want to get well; must seek competent help and cooperate.","Limitation: fits acute illness; chronic disability needs an active 'rehabilitation role' where the patient takes responsibility."]},
    {h:"Application in physiotherapy", p:["Take a social history and plan around work hours, travel and cost; give a simple home programme with pictures.","Explore the patient's explanation of the illness before teaching (for example belief that rest cures back pain).","Move the patient from passive sick role to active participant; involve family.","Advocate for free or low-cost services, government schemes and community programmes."]},
    {h:"Conclusion", p:["Understanding social factors and illness perception helps the physiotherapist reach patients earlier, set realistic goals and improve adherence."]}
  ],
  tip:"Draw the Dahlgren-Whitehead rainbow: individual in the centre, then lifestyle, social networks, living and working conditions, and general socioeconomic and cultural conditions in outer arcs.",
  evidence:[["Socioeconomic position and health","Lower position consistently linked with higher disease and mortality","High"],["Patient education addressing illness beliefs in back pain","Reduces fear and may improve function","Moderate"],["Health literacy-adapted materials","Improve understanding; effect on outcomes varies","Low-moderate"]],
  evidenceSource:"WHO Commission on Social Determinants of Health, Closing the gap in a generation (2008); Marmot Whitehall studies; Parsons, The Social System (1951)",
  outcomes:[["Kuppuswamy socioeconomic scale (updated)","Socioeconomic status in India"],["Illness Perception Questionnaire (Brief IPQ)","Patient's beliefs about illness"],["Attendance and drop-out records","Effect of social barriers on therapy"]],
  recent:["The Kuppuswamy and B G Prasad socioeconomic scales are revised regularly by Indian authors for current income values using the consumer price index."],
  mnemonic:{word:"PEOPLE", items:[["P","Poverty"],["E","Education"],["O","Occupation"],["P","Place: housing, rural or urban"],["L","Lifestyle and culture"],["E","Equity: gender, caste"]], extra:"Disease is what the doctor finds, illness is what the patient feels, sickness is what society recognises."},
  example:"A 40-year-old woman construction worker in Madurai with shoulder pain delays treatment for months because she cannot lose daily wages. The physiotherapist gives early-morning appointments and a short home exercise card she can do at the site.",
  flags:["Delayed presentation due to social factors can hide serious pathology","Do not label culturally different illness behaviour as malingering"],
  viva:[["Give the WHO definition of health.","Complete physical, mental and social well-being, not merely absence of disease or infirmity."],["Who described the sick role?","Talcott Parsons, 1951."],["Difference between disease and illness?","Disease is the biological abnormality; illness is the person's experience of being unwell."]],
  refs:[{b:"park",ch:"Concept of health and disease; social determinants"},{c:"Parsons T. The Social System. Glencoe: Free Press; 1951."},{c:"Mechanic D. The concept of illness behavior. J Chronic Dis. 1962;15:189-194.", q:"Mechanic concept of illness behavior 1962"},{c:"Indrani TK. Textbook of Sociology for Nurses. Jaypee. Chapter: Sociology and health."}],
  keywords:"social determinants of health illness behaviour sick role parsons disease illness sickness poverty education occupation perception of illness",
  mcq:[["According to Parsons, a duty of the sick person is to:",["Avoid doctors","Want to get well and seek help","Return to work at once","Blame the family"],1,"The sick role carries duties as well as rights."],["The patient's own experience of feeling unwell is termed:",["Disease","Sickness","Illness","Disorder"],2,"Illness is subjective; disease is biological; sickness is social."]]
},
{
  id:"ps-socialization", title:"Socialization: process, agencies and socialization in hospital and rehabilitation", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["socialization","agencies of socialization","resocialization","hospital socialization","anticipatory socialization","professional socialization"],
  simple:"Socialization is the lifelong process by which a person learns the language, values, norms and roles of his society. When someone is admitted to hospital or becomes disabled he must learn new roles and rules, which is resocialization. Rehabilitation teams help patients and families adjust to new routines and return to social life.",
  flow:["Socialization: learning norms, values and roles of society","Agencies: family, peers, school, religion, media, workplace","Admission brings new rules, roles and dependence","Disability needs resocialization into new roles","Rehab team, peers and family guide adjustment","Goal: return to family, work and community roles"],
  exam:[
    {h:"Definition", p:["Socialization is the process through which an individual learns and internalises the culture (norms, values, language, roles) of his group and becomes a functioning member of society.","It is lifelong: primary socialization in childhood, secondary in school and work, and resocialization when life changes sharply (illness, disability, migration)."]},
    {h:"Theories", p:["Cooley: looking-glass self - we see ourselves as we imagine others see us.","G H Mead: development of self through play and game stages; 'I' and 'me'.","Freud: id, ego and superego; superego is formed by internalising parental standards."]},
    {h:"Agencies of socialization", p:["Family (most important primary agency), peer group, school and teachers, religion, neighbourhood, mass and social media, workplace and professional bodies, state and law.","Anticipatory socialization: learning a role before entering it (a student learning the physiotherapist role in clinical postings)."]},
    {h:"Socialization in hospital", p:["On admission the patient enters a new social system with its own rules, routines, uniforms and hierarchy; loss of privacy, identity and control.","Patient learns the 'good patient' role; may become passive and dependent (institutionalisation).","Staff socialise patients through orientation, explanation and consistent rules; families are socialised into caregiver roles."]},
    {h:"Socialization in rehabilitation", p:["Disability (spinal cord injury, amputation, stroke) needs resocialization: new body image, new ways of doing daily tasks, new work or school roles.","Physiotherapist helps through goal setting, group therapy, peer mentors (for example a wheelchair user teaching transfers), wheelchair sports and outings.","Family training, home visits and vocational rehabilitation support return to community roles; avoid overprotection and learned helplessness."]},
    {h:"Professional socialization", p:["Students acquire professional values, ethics, communication and team roles through teachers, clinical role models and professional associations."]},
    {h:"Conclusion", p:["Socialization explains how patients adapt to hospital and disability; deliberate resocialization in rehab restores social identity and participation."]}
  ],
  tip:"Draw a timeline arrow from birth to old age with primary, secondary and resocialization phases; put agency icons (family, school, peers, workplace, hospital) along it.",
  evidence:[["Peer support for people with spinal cord injury","May improve self-efficacy and community participation","Low"],["Group-based rehabilitation and exercise classes","Comparable function to individual therapy with social benefits","Low-moderate"]],
  evidenceSource:"Cooley, Human Nature and the Social Order (1902); Mead, Mind, Self and Society (1934); Goffman, Asylums (1961)",
  outcomes:[["Community Integration Questionnaire","Return to home, social and work roles"],["Reintegration to Normal Living Index","Participation after illness"],["General Self-Efficacy Scale","Confidence in new roles"]],
  recent:["Peer mentoring by trained people with spinal cord injury is now part of many rehabilitation programmes worldwide."],
  mnemonic:{word:"FPS-MRW", items:[["F","Family"],["P","Peers"],["S","School"],["M","Media"],["R","Religion"],["W","Workplace"]], extra:"Primary socialization in childhood, secondary in school and work, resocialization after disability."},
  example:"A 22-year-old engineering student in Coimbatore with paraplegia after a bike accident meets a wheelchair basketball player during rehab. Seeing him drive and work, the student starts practising independent transfers and plans to return to college.",
  flags:["Long institutional stay can cause dependency and loss of social skills","Overprotective families can block resocialization"],
  viva:[["Who gave the looking-glass self?","Charles Horton Cooley."],["What is resocialization?","Learning new norms and roles after a major life change such as disability."],["Most important agency of primary socialization?","The family."]],
  refs:[{c:"Shankar Rao CN. Sociology: Principles of Sociology. S Chand. Chapter: Socialization."},{c:"Goffman E. Asylums: Essays on the Social Situation of Mental Patients and Other Inmates. New York: Anchor; 1961."},{b:"park",ch:"Medicine and social sciences"}],
  keywords:"socialization agencies family peers school resocialization hospital rehabilitation cooley looking glass self mead anticipatory professional",
  mcq:[["Learning a role before actually occupying it is:",["Resocialization","Anticipatory socialization","Primary socialization","Deviance"],1,"For example students learning the professional role."],["The 'looking-glass self' concept was proposed by:",["Mead","Durkheim","Cooley","Comte"],2,"Cooley described the self formed from others' imagined view."]]
}
,{
  id:"ps-social-groups", title:"Social groups: primary and secondary groups and their role in rehabilitation", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["social group","primary group Cooley","secondary group","in-group out-group","reference group","self-help groups in rehabilitation"],
  simple:"A social group is two or more people who interact, share a sense of belonging and common goals. Primary groups like family and close friends are small, face-to-face and emotional, while secondary groups like a hospital, a disability association or a workplace are larger, formal and goal-based. Both groups support or hinder a patient's rehabilitation.",
  flow:["Social group: interacting people with shared identity","Primary groups: small, intimate, face-to-face (Cooley)","Secondary groups: large, formal, goal-oriented","Other types: in-group, out-group, reference, peer groups","Rehab uses family, peer and self-help groups","Groups give support, motivation, information and resources"],
  exam:[
    {h:"Definition and characteristics", p:["A social group is a collection of two or more people who interact regularly, share common interests or goals and feel a sense of 'we'.","Features: mutual awareness, reciprocal relations, shared norms, unity, group structure with status and roles."]},
    {h:"Primary group (C H Cooley, 1909)", p:["Small size, face-to-face contact, intimacy, long duration, informal control; relations are ends in themselves.","Examples: family, play group, close friends, neighbourhood.","Importance: first agency of socialization, emotional security, care-giving; the family is the main care team at home after discharge."]},
    {h:"Secondary group", p:["Large, impersonal, formal, contractual, goal-directed, indirect contact; control by rules and law.","Examples: hospital, rehabilitation centre, professional association, trade union, government department, NGO for the disabled."]},
    {h:"Other classifications", p:["In-group and out-group (Sumner): 'we' versus 'they'; disabled people may be treated as an out-group, causing stigma.","Reference group: group whose standards a person uses to judge himself (for example athletes for a sports-injured patient).","Formal and informal, voluntary and involuntary, peer groups, self-help groups."]},
    {h:"Groups in rehabilitation", p:["Primary: family caregivers trained in transfers, positioning, home exercise; emotional support speeds recovery; over-protection or neglect slows it.","Secondary: multidisciplinary team (physiotherapist, occupational therapist, doctor, nurse, social worker, prosthetist) works with shared goals and clear roles.","Group therapy: back school, cardiac and pulmonary rehab classes, stroke circuit classes, falls prevention groups - cost-effective, enjoyable, mutual motivation.","Self-help and peer support groups: Parkinson's, spinal injury, amputee and parents of children with CP groups share coping and resources; women's self-help groups help in CBR."]},
    {h:"Group dynamics in therapy groups", p:["Keep size manageable (about 6-10), set common goals, use a leader, encourage participation and positive peer modelling; watch for dominant members and social comparison that discourages slower patients."]},
    {h:"Conclusion", p:["Primary groups give the emotional base and secondary groups give expert and organised support; rehabilitation succeeds when both are mobilised."]}
  ],
  tip:"Draw a two-column table, Primary vs Secondary group, comparing size, contact, relations, duration, control and examples; add a small circle diagram of the rehab team around the patient.",
  evidence:[["Circuit class therapy after stroke","Improves walking ability and mobility compared with usual care","Moderate"],["Pulmonary rehabilitation delivered in groups","Improves exercise capacity and quality of life in COPD","High"],["Caregiver training after stroke","May reduce caregiver burden and costs","Low-moderate"]],
  evidenceSource:"Cochrane reviews: circuit class therapy for mobility after stroke (English 2017); pulmonary rehabilitation for COPD (McCarthy 2015); Kalra L et al. BMJ 2004 caregiver training",
  outcomes:[["Zarit Burden Interview","Caregiver burden"],["Multidimensional Scale of Perceived Social Support","Social support"],["Group attendance and adherence","Engagement"]],
  recent:["Tele-rehabilitation groups over video call grew after the COVID-19 pandemic, allowing group exercise for patients far from centres."],
  mnemonic:{word:"FIST", items:[["F","Face-to-face (primary)"],["I","Intimate (primary)"],["S","Size large (secondary)"],["T","Task and contract based (secondary)"]], extra:"Cooley described the primary group; Sumner described in-group and out-group."},
  example:"In a Tiruvannamalai village, mothers of children with cerebral palsy form a self-help group. The CBR physiotherapist trains them together on positioning and feeding, and they take turns minding children so each mother can attend therapy.",
  flags:["Group classes need screening; high-risk cardiac patients need individual supervision","Comparison in groups can demotivate slower patients"],
  viva:[["Who coined the term primary group?","Charles Horton Cooley."],["Give two examples of secondary groups in rehabilitation.","Hospital rehab team and a disability rights association."],["What is a reference group?","A group whose standards a person uses to evaluate himself."]],
  refs:[{c:"Cooley CH. Social Organization: A Study of the Larger Mind. New York: Scribner; 1909."},{c:"Shankar Rao CN. Sociology: Principles of Sociology. S Chand. Chapter: Social groups."},{c:"English C, Hillier SL, Lynch EA. Circuit class therapy for improving mobility after stroke. Cochrane Database Syst Rev. 2017.", q:"English circuit class therapy improving mobility after stroke Cochrane"}],
  keywords:"social group primary group secondary group cooley in-group out-group reference group self-help group peer support rehabilitation team group therapy",
  mcq:[["Which is a primary group?",["Trade union","Hospital staff","Family","Political party"],2,"Family is small, intimate and face-to-face."],["'We-feeling' versus 'they-feeling' describes:",["Primary and secondary groups","In-group and out-group","Formal and informal groups","Reference groups"],1,"Sumner's in-group and out-group."]]
},
{
  id:"ps-family-community", title:"Family and community: types, functions, health beliefs, practices and home remedies", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["family types","joint family","nuclear family","functions of family","community health beliefs","home remedies","traditional bone setter"],
  simple:"The family is the basic unit of society and the first place where illness is noticed, explained and cared for. Communities share beliefs about why illness happens and what cures it, including home remedies, oil massage and traditional bone setters. A physiotherapist must respect these beliefs, use the helpful ones and gently correct harmful ones.",
  flow:["Family: basic social unit linked by marriage, blood or adoption","Types: nuclear, joint, extended; changing to nuclear in cities","Functions include care of sick and disabled members","Community shares health beliefs and practices","Home remedies: some useful, some harmful","Physio partners with family and community leaders"],
  exam:[
    {h:"Family: definition and types", p:["Family is a group of people related by marriage, blood or adoption, usually living together and sharing resources.","Types: nuclear (couple and children), joint (several generations and brothers' families with common kitchen and property), extended, three-generation; patriarchal and matriarchal (traditional Kerala Nair system was matrilineal).","Trend in India: shift from joint to nuclear families with urbanisation, migration and women's employment, reducing available caregivers."]},
    {h:"Functions of family", p:["Biological (reproduction), economic, socialization and education, emotional support, protection and care of sick, disabled and elderly, transmission of culture and religion.","In illness: decides when and where to seek care, pays for treatment, provides transport, home care and supervision of exercises."]},
    {h:"Family and disability", p:["Joint family: more hands for care but decisions by elders; nuclear family: less help, caregiver burden on the spouse, often the woman.","Reactions: shock, denial, guilt, overprotection, rejection, hiding a disabled child, financial strain.","Physio: family education, caregiver training (transfers, positioning, home programme), respite and counselling."]},
    {h:"Community: beliefs and practices", p:["Community: people in a locality with common life and sense of belonging; health beliefs are shared and passed on.","Beliefs about causes: karma or past sins, evil eye, hot-cold imbalance, spirits, 'nerve weakness', 'gas', 'vatham'.","Practices: rest and avoidance of movement after injury, confinement after childbirth, fasting, special diets, temple visits, vows, amulets."]},
    {h:"Home remedies and traditional practices", p:["Useful or harmless: turmeric milk, steam inhalation, hot water fomentation, gentle oil massage, ORS, rest in acute injury.","Harmful: tight splinting by traditional bone setters causing Volkmann's ischaemic contracture or malunion, burning (branding) for pain, hot oil on burns, applying cow dung to wounds, prolonged bed rest for back pain.","AYUSH systems (Ayurveda, Siddha, Unani, yoga, homeopathy) are widely used; ask about them and avoid conflict."]},
    {h:"Role of physiotherapist", p:["Take a family and community history; identify key decision-maker and primary caregiver.","Respect beliefs, explain in local language, combine safe traditional practices with exercise, correct dangerous ones tactfully.","Work with community leaders, ASHA and anganwadi workers, self-help groups and religious places for awareness and camps."]},
    {h:"Conclusion", p:["Family and community are the real settings of rehabilitation; understanding their beliefs and practices makes therapy acceptable and lasting."]}
  ],
  tip:"Draw a genogram of three generations (squares male, circles female) with the patient marked and the primary caregiver circled; add a side box of helpful versus harmful home remedies.",
  evidence:[["Family-led rehabilitation after stroke in India (ATTEND trial)","No added benefit over usual care in function at 6 months","High"],["Caregiver training in stroke","May improve caregiver outcomes; results are mixed","Low-moderate"]],
  evidenceSource:"ATTEND Collaborative Group. Family-led rehabilitation after stroke in India. Lancet 2017; Park's Textbook of Preventive and Social Medicine",
  outcomes:[["Zarit Burden Interview","Caregiver strain"],["Family APGAR","Family function"],["Home assessment checklist","Barriers in house and toilet"]],
  recent:["The ATTEND trial (Lancet 2017) found family-led rehabilitation after stroke in India was not superior to usual care, showing family training must be well structured and supported."],
  mnemonic:{word:"BEST", items:[["B","Beliefs about cause"],["E","Explore home remedies"],["S","Safe ones kept"],["T","Tactfully correct harmful ones"]], extra:"Family types: Nuclear, Joint, Extended."},
  example:"A 9-year-old boy in Dharmapuri had a supracondylar fracture tied tightly by a local bone setter; three days later his fingers are pale and cannot extend. The physiotherapist recognises an emergency, refers him at once, and later educates the village about early hospital care.",
  flags:["Tight traditional splints with pain, pallor, pulselessness: compartment syndrome emergency","Prolonged bed rest advice for back pain delays recovery","Hidden disabled child at home: possible neglect"],
  viva:[["Name the types of family.","Nuclear, joint and extended (three-generation)."],["Name a harmful complication of traditional bone setting.","Volkmann's ischaemic contracture or malunion."],["Who is the key person to train for home exercise?","The primary caregiver in the family."]],
  refs:[{b:"park",ch:"Family; medicine and social sciences"},{c:"ATTEND Collaborative Group. Family-led rehabilitation after stroke in India (ATTEND): a randomised controlled trial. Lancet. 2017;390:588-599.", q:"ATTEND family-led rehabilitation stroke India Lancet 2017"},{c:"Indrani TK. Textbook of Sociology for Nurses. Jaypee. Chapter: Family."}],
  keywords:"family nuclear joint extended functions caregiver community health beliefs practices home remedies bone setter volkmann ayush genogram",
  mcq:[["A complication of tight splinting by traditional bone setters is:",["Osteoporosis","Volkmann's ischaemic contracture","Rickets","Gout"],1,"Tight bandaging causes forearm compartment ischaemia."],["The main trend in Indian family structure in cities is:",["Joint to nuclear","Nuclear to joint","Matrilineal to patrilineal","No change"],0,"Urbanisation and migration favour nuclear families."]]
},
{
  id:"ps-culture-sickness", title:"Culture and the meaning of sickness", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["culture definition","culture and health","cultural beliefs about illness","explanatory model Kleinman","cultural competence","stigma of disability"],
  simple:"Culture is the shared way of life of a group: its beliefs, values, language, food, customs and objects. Culture decides what people see as sickness, what they think caused it, whom they consult and how they behave when ill. A culturally competent physiotherapist asks what the illness means to the patient before explaining treatment.",
  flow:["Culture: learned, shared, transmitted way of life","Elements: beliefs, values, norms, language, material objects","Culture shapes meaning and causes given to sickness","Influences pain expression, help-seeking and stigma","Kleinman's explanatory model questions reveal beliefs","Physio gives culturally competent, respectful care"],
  exam:[
    {h:"Definition and characteristics", p:["Tylor (1871): culture is the complex whole that includes knowledge, belief, art, morals, law, custom and other capabilities acquired by man as a member of society.","Characteristics: learned, shared, transmitted across generations, symbolic, dynamic, varies from society to society.","Material culture (tools, buildings, clothing) and non-material culture (ideas, values, customs); cultural lag (Ogburn) when non-material culture lags behind material change."]},
    {h:"Meaning of sickness across cultures", p:["Sickness is socially defined: what counts as illness, normal ageing or a curse differs between groups.","Causal beliefs: natural (cold, diet, injury, germs), supernatural (God's will, karma, evil eye, spirits), social (jealousy, black magic), personal (sin, breaking taboos).","Disability may be seen as punishment for past deeds, bringing shame and hiding of the person; or as fate to be accepted, reducing motivation for rehab."]},
    {h:"Cultural influences on health behaviour", p:["Pain expression: some groups are stoical, others expressive; do not judge severity by expression alone.","Help-seeking: home remedies, temple, faith healers, AYUSH, then allopathy; delay in seeking care.","Gender norms: modesty may require female therapist or chaperone; women may need husband's permission.","Diet, fasting, religious festivals and pilgrimages affect appointments and exercise; floor sitting, squatting and Indian toilets affect functional goals."]},
    {h:"Explanatory model (Arthur Kleinman, 1980)", p:["Ask: What do you call this problem? What caused it? Why now? What does it do to your body? How severe? What treatment do you expect? What do you fear most?","Comparing the patient's and therapist's models allows negotiation of a shared plan."]},
    {h:"Cultural competence in physiotherapy", p:["Awareness of one's own bias; knowledge of local customs; skill in communication in the patient's language or through interpreters.","Adapt exercises to cultural activities (squatting, sitting cross-legged, namaskar, yoga, kolam drawing, household tasks).","Respect privacy and gender preferences, explain touch before handling, involve family elders when appropriate.","Fight stigma through awareness programmes and positive role models."]},
    {h:"Conclusion", p:["Sickness carries cultural meaning; understanding it improves trust, compliance and the relevance of rehabilitation goals."]}
  ],
  tip:"Draw a circle labelled 'Patient's explanatory model' and another 'Therapist's biomedical model' overlapping; label the overlap 'Shared treatment plan'.",
  evidence:[["Cultural competence training for health professionals","Improves professional knowledge and attitudes; effect on patient outcomes uncertain","Low"],["Culturally adapted health education","Can improve knowledge and some outcomes in minority groups","Low-moderate"]],
  evidenceSource:"Kleinman A. Patients and Healers in the Context of Culture (1980); Tylor EB. Primitive Culture (1871); systematic reviews of cultural competence training",
  outcomes:[["Explanatory Model Interview Catalogue (EMIC)","Cultural beliefs about illness"],["Patient satisfaction questionnaire","Acceptability of care"],["Stigma scales","Perceived stigma"]],
  recent:["The DSM-5 (2013) added a Cultural Formulation Interview to help clinicians ask about the cultural meaning of illness."],
  mnemonic:{word:"LEARN", items:[["L","Listen to the patient's view"],["E","Explain your view"],["A","Acknowledge differences"],["R","Recommend treatment"],["N","Negotiate agreement"]], extra:"Berlin and Fowkes LEARN model for cross-cultural communication."},
  example:"A grandmother in a Kanyakumari fishing village believes her grandson's cerebral palsy is a curse and keeps him indoors. The physiotherapist listens first, explains the cause simply, shows a video of a child with CP in school, and involves the local priest in an awareness meeting.",
  flags:["Belief in curse can lead to hiding or neglect of disabled children","Stoical patients may under-report serious pain"],
  viva:[["Who defined culture as the complex whole?","E B Tylor, 1871."],["What is cultural lag?","Delay of non-material culture behind material change (Ogburn)."],["Who gave the explanatory model of illness?","Arthur Kleinman."]],
  refs:[{c:"Kleinman A. Patients and Healers in the Context of Culture. Berkeley: University of California Press; 1980."},{b:"park",ch:"Medicine and social sciences: culture"},{c:"Berlin EA, Fowkes WC. A teaching framework for cross-cultural health care. West J Med. 1983;139:934-938.", q:"Berlin Fowkes LEARN cross-cultural health care 1983"}],
  keywords:"culture tylor material non-material cultural lag ogburn meaning of sickness beliefs evil eye karma explanatory model kleinman cultural competence learn stigma",
  mcq:[["The 'explanatory model' of illness was proposed by:",["Parsons","Kleinman","Tylor","Durkheim"],1,"Kleinman described patients' explanatory models."],["Non-material culture lagging behind technology is called:",["Acculturation","Assimilation","Cultural lag","Diffusion"],2,"Ogburn's concept of cultural lag."]]
}
,{
  id:"ps-caste-system", title:"Caste system: features, changes and influence on health and rehabilitation", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["caste","varna and jati","social stratification India","untouchability","caste and health","reservation"],
  simple:"Caste is a hereditary system of social ranking in India where a person's group is fixed by birth and traditionally decided occupation, marriage and social contact. The Constitution has abolished untouchability and bans caste discrimination, but caste still affects income, education and access to health care. A physiotherapist must treat every patient equally and understand caste-linked barriers.",
  flow:["Caste: hereditary, endogamous, ranked social group","Varna (four orders) and jati (many local groups)","Features: birth status, endogamy, occupation, purity rules","Changes: law, education, urbanisation, reservation","Caste affects income, health access and discrimination","Physio gives equal care and links to welfare schemes"],
  exam:[
    {h:"Definition", p:["Caste is a closed system of social stratification in which membership is ascribed by birth, marriage is within the group (endogamy) and groups are ranked in a hierarchy.","Varna: four traditional orders (Brahmin, Kshatriya, Vaishya, Shudra); jati: thousands of local occupational and kinship groups that actually operate in daily life.","Social stratification: ranking of people into layers; caste is closed, class (based on income and occupation) is open."]},
    {h:"Features (G S Ghurye)", p:["Segmental division of society; hierarchy; restrictions on feeding and social intercourse; civil and religious privileges and disabilities; lack of free choice of occupation; restrictions on marriage (endogamy)."]},
    {h:"Merits and demerits", p:["Merits claimed historically: social security within the group, transmission of skills, mutual help.","Demerits: inequality, untouchability, exploitation, barrier to national unity, wasted talent, honour violence, poor access to education and health for lower castes."]},
    {h:"Changes in the caste system", p:["Constitution: Article 15 forbids discrimination; Article 17 abolishes untouchability; Protection of Civil Rights Act 1955; SC and ST (Prevention of Atrocities) Act 1989.","Reservation in education, jobs and legislatures for Scheduled Castes, Scheduled Tribes and Other Backward Classes.","Forces of change: education, urbanisation, industrialisation, transport, mass media, inter-caste marriage, democracy; Sanskritisation (M N Srinivas) and westernisation.","But caste persists in marriage, politics and rural social life."]},
    {h:"Caste and health", p:["Lower caste groups often have more poverty, malnutrition, hazardous occupations (manual scavenging, construction, leather work) and lower access to care.","Discrimination may cause reluctance to visit hospitals; dietary rules and purity beliefs may affect acceptance of touch or shared equipment.","Disability in poor and marginalised families compounds disadvantage."]},
    {h:"Application in physiotherapy", p:["Ethical duty of equal, respectful care regardless of caste; no discrimination in touch, seating or waiting.","Be aware of occupation-related injuries and economic barriers; link patients to free schemes (Chief Minister's insurance schemes, Ayushman Bharat PM-JAY) and disability certificates.","In community work, include all hamlets and colonies; choose camp sites accessible to everyone."]},
    {h:"Conclusion", p:["Although outlawed as a basis for discrimination, caste still shapes health; physiotherapists must practise equity and help remove social barriers to rehabilitation."]}
  ],
  tip:"Draw a closed pyramid for caste and an open ladder for class side by side, with arrows showing mobility only in the ladder; list Ghurye's six features beside it.",
  evidence:[["Social disadvantage (caste, class) and health outcomes in India","Marginalised castes show worse health indicators in national surveys","Moderate"],["Health insurance for poor households","Improves access to hospital care; effect on outcomes still being studied","Low"]],
  evidenceSource:"National Family Health Survey (NFHS) reports, Government of India; Ghurye GS. Caste and Race in India (1932)",
  outcomes:[["Kuppuswamy socioeconomic scale","Socioeconomic status"],["Attendance and drop-out audit","Equity of access"],["Patient-reported respect and satisfaction","Perceived discrimination"]],
  recent:["Ayushman Bharat PM-JAY (2018) provides hospital insurance cover for poorer families, helping access to surgery and inpatient rehabilitation."],
  mnemonic:{word:"SHRCOE", items:[["S","Segmental division"],["H","Hierarchy"],["R","Restrictions on feeding and contact"],["C","Civil and religious privileges and disabilities"],["O","Occupation not freely chosen"],["E","Endogamy"]], extra:"Ghurye's six features. Article 17 abolishes untouchability."},
  example:"A 35-year-old sanitation worker in Vellore with chronic low back pain stops attending therapy after feeling ignored in the waiting area. The physiotherapist ensures equal queueing, explains exercises respectfully and links him to a government insurance scheme.",
  flags:["Discrimination by staff is unethical and illegal","Hazardous occupations (manual scavenging) carry infection and injury risk"],
  viva:[["Which Article abolishes untouchability?","Article 17."],["Difference between caste and class?","Caste is closed and ascribed by birth; class is open and based on achievement and income."],["Who coined Sanskritisation?","M N Srinivas."]],
  refs:[{c:"Ghurye GS. Caste and Race in India. Bombay: Popular Prakashan."},{c:"Shankar Rao CN. Sociology: Principles of Sociology. S Chand. Chapter: Caste system in India."},{c:"Srinivas MN. Social Change in Modern India. Orient Longman; 1966."},{b:"park",ch:"Medicine and social sciences"}],
  keywords:"caste varna jati endogamy hierarchy ghurye untouchability article 17 reservation sanskritisation srinivas stratification class health equity",
  mcq:[["Marriage within one's own caste is called:",["Exogamy","Endogamy","Polygamy","Hypergamy"],1,"Endogamy is the core rule of caste."],["Sanskritisation was described by:",["G S Ghurye","M N Srinivas","Max Weber","Auguste Comte"],1,"Srinivas described lower castes adopting upper caste customs."]]
},
{
  id:"ps-social-change", title:"Social change and stress, deviant behaviour and health programmes", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["social change","factors of social change","urbanisation and health","deviance","anomie Durkheim","national health programmes"],
  simple:"Social change is any lasting change in the structure, values and ways of life of a society, such as urbanisation, industrialisation and new technology. Fast change brings stress, loss of family support and lifestyle diseases, and can increase deviant behaviour like substance abuse and crime. Health programmes are society's planned response to these problems.",
  flow:["Social change: alteration of social structure and behaviour","Factors: technology, economy, education, population, culture","Rapid change causes role conflict, isolation and stress","Stress links to lifestyle disease and deviant behaviour","Deviance: breaking norms; anomie, strain theories","Health programmes respond: NCD, elderly, mental health"],
  exam:[
    {h:"Social change: definition and factors", p:["Social change is a significant alteration over time in social structure, institutions, relationships and cultural patterns.","Factors: technological (machines, mobile phones, internet), economic (industrialisation, globalisation), demographic (population growth, ageing, migration), cultural and ideological, education, legislation, mass media, natural disasters and war.","Theories: evolutionary, cyclical, conflict (Marx), functionalist; Ogburn's cultural lag."]},
    {h:"Social change and stress", p:["Urbanisation and migration: nuclear families, loss of joint family support, crowded housing, long commutes.","Industrial and IT work: shift work, job insecurity, sedentary life, competition.","Results: psychological stress, anxiety, depression, hypertension, diabetes, obesity, musculoskeletal pain (text neck, low back pain), isolation of the elderly, family breakdown.","Holmes and Rahe Social Readjustment Rating Scale (1967) rates life changes as stressors."]},
    {h:"Deviant behaviour", p:["Deviance: behaviour that violates the norms of a group or society; may be positive or negative and is culturally relative.","Theories: Durkheim's anomie (normlessness during rapid change); Merton's strain theory (gap between goals and means: conformity, innovation, ritualism, retreatism, rebellion); labelling theory (Becker); differential association (Sutherland).","Examples relevant to health: substance abuse, suicide, delinquency, road rage, non-compliance, malingering."]},
    {h:"Health programmes as planned social change", p:["National Programme for Prevention and Control of Cancer, Diabetes, Cardiovascular Diseases and Stroke (NPCDCS, now NP-NCD), National Programme for Health Care of the Elderly (NPHCE), National Mental Health Programme, National Tobacco Control Programme, Rashtriya Bal Swasthya Karyakram (screening children for defects, diseases and disabilities with District Early Intervention Centres).","Fit India Movement (2019) promotes physical activity; Health and Wellness Centres (Ayushman Arogya Mandirs) bring NCD care to villages."]},
    {h:"Role of physiotherapist", p:["Lifestyle counselling, exercise prescription and stress management (relaxation, breathing, yoga) for NCD prevention.","Ergonomic advice for IT workers and students; falls prevention and activity for the elderly left alone.","Take part in screening camps and national programmes; identify early disability in children (RBSK)."]},
    {h:"Conclusion", p:["Social change brings both progress and stress; physiotherapists help society adapt through prevention, activity promotion and participation in health programmes."]}
  ],
  tip:"Draw a flow: Social change (urbanisation, technology) leads to Stress and lifestyle change, then to NCDs and deviance, and finally Health programmes and Physio role as the response arrow.",
  evidence:[["Exercise programmes for prevention of type 2 diabetes in high-risk people","Lifestyle intervention reduces diabetes incidence","High"],["Workplace ergonomic and exercise programmes","Small reduction in neck and back pain","Low-moderate"],["Yoga for stress and anxiety","Small to moderate short-term benefits","Low-moderate"]],
  evidenceSource:"Indian Diabetes Prevention Programme (Ramachandran 2006, Diabetologia); Durkheim, Suicide (1897); Merton, Social Structure and Anomie (1938)",
  outcomes:[["Perceived Stress Scale","Stress level"],["Holmes and Rahe scale","Life-change load"],["Physical activity questionnaire (IPAQ)","Activity level"]],
  recent:["The Fit India Movement launched in 2019 and the Health and Wellness Centres under Ayushman Bharat promote physical activity and NCD screening in the community."],
  mnemonic:{word:"TEMPLE", items:[["T","Technology"],["E","Economy"],["M","Media"],["P","Population"],["L","Law and legislation"],["E","Education"]], extra:"Merton's modes: Conformity, Innovation, Ritualism, Retreatism, Rebellion."},
  example:"A 28-year-old software engineer who moved from a Kumbakonam joint family to Bengaluru develops neck pain, poor sleep and weight gain. The physiotherapist addresses workstation ergonomics, a walking plan and breathing relaxation.",
  flags:["Stress with suicidal ideas needs urgent referral","Substance misuse may hide behind 'stress' complaints"],
  viva:[["What is anomie?","Normlessness during rapid social change, described by Durkheim."],["Name Merton's five modes of adaptation.","Conformity, innovation, ritualism, retreatism, rebellion."],["Which programme screens children for disabilities in India?","Rashtriya Bal Swasthya Karyakram (RBSK)."]],
  refs:[{b:"park",ch:"Health programmes in India; non-communicable diseases"},{c:"Shankar Rao CN. Sociology: Principles of Sociology. S Chand. Chapter: Social change."},{c:"Holmes TH, Rahe RH. The Social Readjustment Rating Scale. J Psychosom Res. 1967;11:213-218.", q:"Holmes Rahe social readjustment rating scale 1967"}],
  keywords:"social change urbanisation industrialisation stress deviance anomie durkheim merton strain labelling health programmes npcdcs nphce rbsk fit india",
  mcq:[["'Anomie' as a cause of deviance was described by:",["Merton","Durkheim","Becker","Weber"],1,"Durkheim linked normlessness to deviance and suicide."],["In Merton's theory, rejecting both goals and means and withdrawing (as in drug addiction) is:",["Innovation","Ritualism","Retreatism","Conformity"],2,"Retreatists withdraw from society."]]
},
{
  id:"ps-social-control", title:"Social control: norms, folkways, mores, customs and law", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["social control","social norms","folkways and mores","customs","law and social control","formal and informal control"],
  simple:"Social control is the set of ways a society keeps people's behaviour in line with its rules. Informal controls are folkways, mores, customs, religion and gossip; formal controls are laws, police and courts. In health care, norms and professional codes guide how therapists and patients behave.",
  flow:["Social control keeps behaviour within accepted norms","Norms: shared expectations of right behaviour","Folkways: everyday habits, mild sanctions","Mores: moral rules, strong sanctions; taboos","Customs and law: tradition versus formal state rules","Health: professional ethics, patient rights, health laws"],
  exam:[
    {h:"Definition and need", p:["Social control is the process by which society regulates the behaviour of its members to maintain order, conformity and stability (E A Ross introduced the term).","Need: to maintain social order, ensure cooperation, protect weaker members, and transmit culture."]},
    {h:"Types", p:["Formal: deliberate, written, enforced by authorised agencies (law, police, courts, administrative rules, hospital regulations).","Informal: unwritten, enforced by the group (folkways, mores, customs, religion, morality, public opinion, praise and ridicule).","Positive (rewards) and negative (punishment) sanctions."]},
    {h:"Norms, folkways and mores (W G Sumner, 1906)", p:["Norms: shared standards of expected behaviour.","Folkways: everyday conventions (greeting elders, removing footwear before entering home, eating with right hand); violation brings mild disapproval.","Mores: norms with strong moral value (no theft, care of parents); violation brings strong disapproval; taboos are strongly forbidden acts."]},
    {h:"Customs and law", p:["Customs: long-established, socially accepted practices handed down through generations; slow to change; may be helpful (hand washing) or harmful (child marriage).","Law: formal rules made and enforced by the state with defined penalties; can change customs (Dowry Prohibition Act 1961, Child Marriage Restraint and Prohibition Acts).","Other agencies: family, religion, education, public opinion, mass media, leadership."]},
    {h:"Social control in health care and physiotherapy", p:["Professional norms and codes of ethics: confidentiality, informed consent, respect, appropriate touch and draping.","Laws relevant to practice: Consumer Protection Act (health services), Rights of Persons with Disabilities Act 2016, National Commission for Allied and Healthcare Professions Act 2021, Motor Vehicles Act (helmet and seat belt rules preventing injuries).","Hospital rules (visiting hours, infection control) and group norms in therapy classes; norms can also stigmatise the disabled."]},
    {h:"Conclusion", p:["Social control maintains order through informal norms and formal law; understanding it helps physiotherapists respect customs, follow legal duties and use group norms to promote healthy behaviour."]}
  ],
  tip:"Draw a ladder of increasing strength of sanction: Folkways (bottom), Mores, Customs, Law (top), with an example on each rung; divide sides into Informal and Formal.",
  evidence:[["Helmet laws and enforcement","Increase helmet use and reduce head injuries","Moderate"],["Smoke-free laws","Reduce exposure to second-hand smoke and related hospital admissions","Moderate"]],
  evidenceSource:"Cochrane reviews of motorcycle helmet legislation and of legislative smoking bans; Sumner, Folkways (1906); Ross, Social Control (1901)",
  outcomes:[["Compliance with professional code audit","Ethical practice"],["Informed consent documentation","Legal practice"]],
  recent:["The National Commission for Allied and Healthcare Professions Act, 2021 created a statutory regulatory framework for physiotherapy and other allied health professions in India."],
  mnemonic:{word:"FMCL", items:[["F","Folkways - mild"],["M","Mores - moral, strong"],["C","Customs - traditional"],["L","Law - formal, state"]], extra:"Formal controls are written and enforced by agencies; informal ones by the group."},
  example:"In a Salem rehabilitation ward, a new norm is set that every patient walks to the dining area for lunch. Peer pressure and praise from staff quickly make walking part of the ward routine.",
  flags:["Breach of consent or confidentiality has legal consequences","Customs such as hiding disabled members violate their rights"],
  viva:[["Who introduced folkways and mores?","W G Sumner, 1906."],["Give an example of formal social control.","Law enforced by police and courts."],["What is a taboo?","A strongly forbidden act within mores."]],
  refs:[{c:"Sumner WG. Folkways. Boston: Ginn; 1906."},{c:"Shankar Rao CN. Sociology: Principles of Sociology. S Chand. Chapter: Social control."},{c:"Indrani TK. Textbook of Sociology for Nurses. Jaypee. Chapter: Social control."}],
  keywords:"social control norms folkways mores taboo customs law sumner ross formal informal sanctions professional ethics nchap act",
  mcq:[["Norms with strong moral significance whose breach invites severe disapproval are:",["Folkways","Mores","Fashions","Fads"],1,"Mores carry moral force."],["Which is a formal means of social control?",["Gossip","Folkways","Law","Religion"],2,"Law is written and enforced by the state."]]
}
,{
  id:"ps-disability-social-problems", title:"Social problems of the disabled: poverty, unemployment, beggary, alcoholism and stigma", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["social problems of disabled","disability and poverty","beggary","stigma and discrimination","handicap","social model of disability"],
  simple:"People with disability often face poverty, unemployment, lack of education, stigma, isolation and inaccessible buildings and transport. Poverty and disability feed each other in a vicious circle, and some disabled people are pushed into begging or alcohol use. Rehabilitation must therefore include vocational training, social support and links to welfare schemes, not only exercises.",
  flow:["Impairment plus barriers produce disability and handicap","Poverty and disability form a vicious circle","Problems: unemployment, illiteracy, stigma, isolation, abuse","Extreme results: beggary, alcoholism, family breakdown","Assess social needs and participation (ICF)","Solve through CBR, vocational rehab, schemes, advocacy"],
  exam:[
    {h:"Concepts", p:["WHO 1980 ICIDH: impairment (loss of structure or function), disability (restriction of activity), handicap (social disadvantage).","WHO ICF 2001: body functions and structures, activity, participation, with environmental and personal factors.","Medical model sees disability as a problem of the individual; social model sees it as caused by barriers in society."]},
    {h:"Poverty and disability", p:["Poverty causes disability: malnutrition, poor sanitation, unsafe work, lack of immunisation (polio), poor antenatal care, untreated injuries.","Disability causes poverty: loss of earning, cost of treatment and aids, a family member stops work to give care.","This vicious circle is strongest in rural and urban slum families."]},
    {h:"Other social problems", p:["Unemployment and underemployment; illiteracy and school dropout because of inaccessible schools.","Stigma and discrimination: beliefs in curse or karma, teasing, exclusion from marriage and social functions; women and girls with disability face double discrimination and higher risk of abuse.","Isolation, dependency, depression; architectural and transport barriers; lack of information about rights."]},
    {h:"Beggary and alcoholism", p:["Beggary: some disabled people, abandoned or exploited by gangs, are forced to beg; it brings malnutrition, exposure, exploitation and loss of dignity. Anti-begging laws (for example Bombay Prevention of Begging Act 1959) treated begging as an offence; the Delhi High Court in 2018 decriminalised begging in Delhi, and rehabilitation rather than punishment is the modern approach.","Alcoholism: may follow frustration and unemployment after disability, or cause disability (road accidents, neuropathy, falls); leads to family violence, debt and poor adherence to rehab."]},
    {h:"Role of physiotherapist and rehabilitation team", p:["Assess participation and social needs, not just impairment; refer to social worker and counsellor.","Maximise independence with mobility aids, wheelchair skills, ADL training and home modification.","Vocational rehabilitation: work hardening, job-specific training, links to Vocational Rehabilitation Centres for Handicapped and self-employment schemes.","Community-based rehabilitation (WHO CBR matrix: health, education, livelihood, social, empowerment); awareness against stigma; help with disability certificate and UDID card; screen for alcohol use and give brief advice."]},
    {h:"Conclusion", p:["Social problems often disable more than the impairment itself; physiotherapists must work with the community and welfare systems to break the poverty-disability cycle."]}
  ],
  tip:"Draw the poverty-disability vicious circle: Poverty, Malnutrition and poor care, Impairment, Loss of income, Deeper poverty, with an arrow labelled 'CBR and vocational rehab' breaking the circle.",
  evidence:[["Community-based rehabilitation","May improve function, participation and quality of life; evidence base is weak","Low"],["Vocational rehabilitation after spinal cord injury or brain injury","Supported employment improves return to work","Low-moderate"]],
  evidenceSource:"WHO and World Bank, World Report on Disability (2011); WHO Community-Based Rehabilitation Guidelines (2010)",
  outcomes:[["WHODAS 2.0","Disability and participation"],["Community Integration Questionnaire","Social and work integration"],["Employment status","Economic participation"]],
  recent:["The UDID (Unique Disability ID) card system gives a single national disability certificate and ID to access schemes across India."],
  mnemonic:{word:"PUBLIC", items:[["P","Poverty"],["U","Unemployment"],["B","Beggary"],["L","Lack of education and access"],["I","Isolation and stigma"],["C","Consumption of alcohol and drugs"]], extra:"ICIDH: Impairment, Disability, Handicap. ICF: Body, Activity, Participation, plus context."},
  example:"A 30-year-old man in Tirunelveli with a below-knee amputation lost his loading job and began drinking. The physiotherapist fits gait training with a free prosthesis under a government scheme, the social worker links him to a loan for a small shop, and the doctor refers him for de-addiction.",
  flags:["Signs of abuse or neglect of a disabled person must be reported","Depression and suicidal ideas after disability need urgent referral","Alcohol intoxication makes gait and transfer training unsafe"],
  viva:[["Differentiate impairment, disability and handicap.","Impairment is loss of structure or function; disability is activity restriction; handicap is the social disadvantage that results."],["What are the components of the WHO CBR matrix?","Health, education, livelihood, social and empowerment."],["What does the social model of disability say?","Disability results mainly from barriers in society rather than the individual's impairment."]],
  refs:[{c:"World Health Organization, World Bank. World Report on Disability. Geneva: WHO; 2011."},{c:"World Health Organization. Community-Based Rehabilitation: CBR Guidelines. Geneva: WHO; 2010."},{c:"Ahuja R. Social Problems in India. Jaipur: Rawat Publications. Chapter: Beggary; Alcoholism."},{b:"park",ch:"Rehabilitation; social problems"}],
  keywords:"social problems disabled poverty disability vicious circle unemployment beggary alcoholism stigma handicap icidh icf social model cbr vocational rehabilitation",
  mcq:[["In ICIDH, the social disadvantage arising from impairment is:",["Disability","Handicap","Activity","Pathology"],1,"Handicap is the social consequence."],["The social model of disability places the main cause of disability in:",["Genes","The individual's impairment","Barriers in society","Medical treatment"],2,"Society's barriers disable people."]]
},
{
  id:"ps-disability-legislation", title:"Social security and legislation for the disabled in India", subject:"Psychology and sociology", region:"Sociology", stages:"steps",
  aliases:["RPwD Act 2016","PWD Act 1995","disability legislation India","social security for disabled","National Trust Act","RCI Act","UNCRPD"],
  simple:"Social security means the protection society gives its members against loss of income from sickness, disability, old age or unemployment. India protects disabled people mainly through the Rights of Persons with Disabilities Act 2016, which recognises 21 disabilities and gives reservations, free education and accessibility rights. Physiotherapists help patients get disability certificates, aids and benefits under these laws and schemes.",
  flow:["Social security: social insurance plus social assistance","International basis: UNCRPD 2006, ratified by India 2007","RPwD Act 2016 replaced PWD Act 1995","Other acts: RCI 1992, National Trust 1999, Mental Healthcare 2017","Schemes: pensions, ADIP aids, UDID, Accessible India","Physio helps with certification, aids and access"],
  exam:[
    {h:"Social security: definition and forms", p:["Social security is protection provided by society through public measures against economic and social distress from sickness, maternity, injury, disability, old age, unemployment or death.","Social insurance (contributory): Employees' State Insurance Act 1948 (ESI) gives medical care, sickness and disablement benefit to insured workers; Employees' Compensation Act 1923 (earlier Workmen's Compensation) for work injuries.","Social assistance (non-contributory): pensions and welfare schemes funded by government."]},
    {h:"Rights of Persons with Disabilities Act 2016", p:["Replaced the Persons with Disabilities (Equal Opportunities, Protection of Rights and Full Participation) Act 1995, which covered 7 disabilities and 3% job reservation.","Recognises 21 disabilities, including locomotor disability, cerebral palsy, muscular dystrophy, multiple sclerosis, Parkinson's disease, dwarfism, acid attack victims, leprosy cured, specific learning disability, autism and chronic neurological conditions.","Benchmark disability: at least 40% of a specified disability as certified.","Benefits: 4% reservation in government jobs, at least 5% reserved seats in government and aided higher education, free education for children with benchmark disability aged 6-18, accessibility of buildings, transport and ICT within set time limits, Chief Commissioner and State Commissioners, special courts and penalties for discrimination."]},
    {h:"Other laws", p:["Rehabilitation Council of India Act 1992: regulates training and registration of rehabilitation professionals.","National Trust Act 1999: welfare of persons with autism, cerebral palsy, intellectual disability and multiple disabilities; legal guardianship and schemes such as Niramaya health insurance.","Mental Healthcare Act 2017: rights of persons with mental illness; UNCRPD (2006) ratified by India in 2007.","Income tax relief: Section 80U (person with disability) and 80DD (dependant with disability)."]},
    {h:"Welfare schemes and services", p:["Indira Gandhi National Disability Pension Scheme for BPL persons with severe disability; state monthly maintenance allowances.","ADIP scheme: free or subsidised aids and appliances (wheelchairs, tricycles, calipers, prostheses, hearing aids).","Deendayal Disabled Rehabilitation Scheme (support to NGOs), District Disability Rehabilitation Centres, Composite Regional Centres and National Institutes.","Accessible India Campaign (Sugamya Bharat Abhiyan, 2015); UDID card; railway and bus concessions; scholarships; skill training and self-employment loans."]},
    {h:"Role of physiotherapist", p:["Assess and document function for disability certification by the medical board.","Prescribe and train with aids obtained through ADIP and camps; advise on accessible home and workplace.","Inform patients and families about rights, pensions, reservations and UDID; refer to social worker and DDRC; advocate for ramps and accessible facilities."]},
    {h:"Conclusion", p:["Laws and social security turn disability rights into real benefits; physiotherapists are a key link between the disabled person and these entitlements."]}
  ],
  tip:"Draw a timeline: 1923 Employees' Compensation, 1948 ESI, 1992 RCI, 1995 PWD, 1999 National Trust, 2006 UNCRPD, 2016 RPwD, 2017 Mental Healthcare Act; box the RPwD key numbers (21, 40%, 4%, 5%).",
  evidence:[["Provision of appropriate wheelchairs with training","Improves mobility and participation","Low-moderate"],["Accessibility legislation","Improves physical access over time; enforcement often weak","Low"]],
  evidenceSource:"The Rights of Persons with Disabilities Act, 2016 (Government of India); UN Convention on the Rights of Persons with Disabilities (2006); WHO Guidelines on the provision of manual wheelchairs (2008)",
  outcomes:[["Disability certificate percentage","Severity for benefits"],["Wheelchair Skills Test","Use of provided aids"],["Access audit of building","Barrier-free environment"]],
  recent:["The RPwD Act 2016 expanded recognised disabilities from 7 to 21 and raised job reservation from 3% to 4%."],
  mnemonic:{word:"21-40-4-5", items:[["21","Disabilities recognised"],["40","Percent benchmark disability"],["4","Percent reservation in government jobs"],["5","Percent seats in higher education"]], extra:"Older PWD Act 1995: 7 disabilities, 3% reservation."},
  example:"A 16-year-old girl in Erode with spastic diplegia gets her UDID card after a board assessment supported by her physiotherapist's functional report. She receives a wheelchair through an ADIP camp and later a reserved seat in a college.",
  flags:["Incorrect or exaggerated certification is unethical and illegal","Ill-fitting aids from camps can cause pressure sores or falls; always fit and train"],
  viva:[["How many disabilities are recognised under the RPwD Act 2016?","21."],["What is benchmark disability?","At least 40% of a specified disability as certified."],["Which Act regulates rehabilitation professionals' training?","Rehabilitation Council of India Act, 1992."]],
  refs:[{c:"Government of India. The Rights of Persons with Disabilities Act, 2016 (Act No. 49 of 2016)."},{c:"United Nations. Convention on the Rights of Persons with Disabilities. New York: UN; 2006."},{b:"park",ch:"Rehabilitation; social security"},{c:"Government of India. The National Trust for Welfare of Persons with Autism, Cerebral Palsy, Mental Retardation and Multiple Disabilities Act, 1999."}],
  keywords:"social security disability legislation rpwd act 2016 pwd act 1995 benchmark disability reservation rci act national trust uncrpd esi adip udid accessible india pension",
  mcq:[["Under the RPwD Act 2016, reservation in government jobs for persons with benchmark disability is:",["3%","4%","5%","10%"],1,"Raised from 3% under the 1995 Act to 4%."],["The Act that regulates training of rehabilitation professionals in India is the:",["National Trust Act 1999","ESI Act 1948","RCI Act 1992","Mental Healthcare Act 2017"],2,"The Rehabilitation Council of India Act 1992."]]
}
]);
